            let result = parser.process();
            match result {
                Ok(nodes) => {
                    let transformed = render_transform(&nodes);
                    let _ = out.write_all(transformed.as_bytes());
                    if transformed != content {
                        ProcessResult::Changed
                    } else {
                        ProcessResult::Ok
                    }
                }
                Err(_) => ProcessResult::Error,
            }
        }
        OutputMode::Syntax => {
            let result = parser.process();
            match result {
