            let result = parser.process();
            match result {
                Ok(nodes) => {
                    let output = render_suggest(&nodes);
                    let _ = out.write_all(output.as_bytes());
                    let transformed = render_transform(&nodes);
                    if transformed != content {
                        ProcessResult::Changed
                    } else {
