// === Parser ===

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
    filename: Option<&'a str>,
    had_error: bool,
    // Buffer for partial output on error
    partial_output: Vec<Node>,
}

impl<'a> Parser<'a> {
    fn new(content: &'a str, filename: Option<&'a str>) -> Self {
        Parser {
            input: content.as_bytes(),
            pos: 0,
            filename,
            had_error: false,
            partial_output: Vec::new(),
        }
    }

    fn process(&mut self) -> Result<Vec<Node>, ()> {
        let nodes = self.parse_script();
        if self.had_error {
            Err(())
        } else {
            Ok(nodes)
        }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }

    fn peek2(&self) -> Option<u8> {
        self.input.get(self.pos + 1).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let c = self.input.get(self.pos).copied();
        if c.is_some() { self.pos += 1; }
        c
    }

    fn remaining(&self) -> &[u8] {
        &self.input[self.pos..]
    }

    fn parse_script(&mut self) -> Vec<Node> {
        let mut nodes = Vec::new();
        self.skip_whitespace_and_newlines_to_nodes(&mut nodes);
        while self.pos < self.input.len() {
            if let Some(node) = self.parse_statement() {
                nodes.push(node);
            }
            self.skip_whitespace_and_newlines_to_nodes(&mut nodes);
        }
        nodes
    }

    fn skip_whitespace_and_newlines_to_nodes(&mut self, nodes: &mut Vec<Node>) {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c == b'\n' || c == b'\r' || c == b'\t' || c == b' ' {
                self.advance();
            } else {
                break;
            }
        }
        if self.pos > start {
            let text = std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("");
            if !text.is_empty() {
