use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

const VERSION: &str = "4.3.1";
const COLOR_RESET: &str = "\x1b[m";
const COLOR_COMMENT: &str = "\x1b[0;1;3;38;2;120;144;96m";
const COLOR_COMMAND: &str = "\x1b[0;38;2;192;0;128m";
const COLOR_DOUBLE_QUOTE: &str = "\x1b[0;38;2;255;0;0m";
const COLOR_SINGLE_QUOTE: &str = "\x1b[0;38;2;255;204;85m";
const COLOR_VARIABLE: &str = "\x1b[0;38;2;63;127;207m";
const COLOR_ASSIGN_LHS: &str = "\x1b[0;38;2;0;127;255m";
const COLOR_ARITHMETIC: &str = "\x1b[0;38;2;192;0;192m";
const COLOR_HEREDOC: &str = "\x1b[0;38;2;128;32;0m";
const COLOR_KEYWORD: &str = "\x1b[0;1m";
