// ================================================================
// PARSER - the core of shellharden
// ================================================================

struct Parser {
    input: Vec<u8>,
    pos: usize,
    filename: Option<String>,
    pub had_error: bool,
}

impl Parser {
    fn new(content: &str, filename: Option<&str>) -> Self {
        Parser {
            input: content.as_bytes().to_vec(),
            pos: 0,
            filename: filename.map(|s| s.to_string()),
            had_error: false,
        }
    }

    fn peek(&self) -> Option<u8> { self.input.get(self.pos).copied() }
    fn peek_at(&self, off: usize) -> Option<u8> { self.input.get(self.pos + off).copied() }
    fn advance(&mut self) -> Option<u8> {
        let c = self.input.get(self.pos).copied();
        if c.is_some() { self.pos += 1; }
        c
    }
    fn starts_with(&self, s: &[u8]) -> bool {
        self.input[self.pos..].starts_with(s)
    }
    fn rest(&self) -> &[u8] { &self.input[self.pos..] }
    fn len(&self) -> usize { self.input.len() }

    fn error(&mut self, msg: &str, line: &str, col: usize) {
        let fname = self.filename.as_deref().unwrap_or("stdin");
        eprintln!("{}: Unsupported syntax: {}", fname, msg);
        eprintln!("{}", line);
        let spaces: String = std::iter::repeat(' ').take(col).collect();
        eprintln!("{}^^^", spaces);
    }

    fn eof_error(&mut self) {
        let fname = self.filename.as_deref().unwrap_or("stdin");
        eprintln!("{}: Unexpected end of file", fname);
        eprintln!("The file's end was reached without closing all sytactic scopes.");
        eprintln!("Either, the parser got lost, or the file is truncated or malformed.");
    }
}

fn parse_content(content: &str, filename: Option<&str>) -> Result<Vec<Seg>, ()> {
    let mut parser = Parser::new(content, filename);
    let segs = parse_script(&mut parser);
    if parser.had_error { Err(()) } else { Ok(segs) }
}

fn ic(c: u8) -> bool { c.is_ascii_alphanumeric() || c == b'_' }
fn is_start(c: u8) -> bool { c.is_ascii_alphabetic() || c == b'_' }

fn parse_script(p: &mut Parser) -> Vec<Seg> {
    let mut segs = Vec::new();
    while p.pos < p.len() {
        let start = p.pos;
        parse_statement(p, &mut segs, &[]);
        if p.pos == start {
            // No progress - consume one char to avoid infinite loop
            let c = p.advance().unwrap_or(b'\n');
            push_verb(&mut segs, &[c]);
        }
    }
    segs
}

fn push_verb(segs: &mut Vec<Seg>, bytes: &[u8]) {
    if bytes.is_empty() { return; }
    let s = String::from_utf8_lossy(bytes).to_string();
    if let Some(Seg::Verbatim(ref mut prev)) = segs.last_mut() {
        prev.push_str(&s);
    } else {
        segs.push(Seg::Verbatim(s));
    }
}

fn push_verb_str(segs: &mut Vec<Seg>, s: &str) {
    if s.is_empty() { return; }
    if let Some(Seg::Verbatim(ref mut prev)) = segs.last_mut() {
        prev.push_str(s);
    } else {
        segs.push(Seg::Verbatim(s.to_string()));
    }
}

// Skip whitespace/newlines
fn skip_ws(p: &mut Parser, segs: &mut Vec<Seg>) {
    let start = p.pos;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
            p.pos += 1;
        } else if c == b'\\' && p.peek_at(1) == Some(b'\n') {
            p.pos += 2;
        } else {
            break;
        }
    }
    if p.pos > start {
        push_verb(segs, &p.input[start..p.pos].to_vec());
    }
}

fn skip_inline_ws(p: &mut Parser, segs: &mut Vec<Seg>) {
    let start = p.pos;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b' ' || c == b'\t' {
            p.pos += 1;
        } else {
            break;
        }
    }
    if p.pos > start {
        push_verb(segs, &p.input[start..p.pos].to_vec());
    }
}

// Check if next word is a stop token
fn at_stop(p: &Parser, stops: &[&str]) -> bool {
    for stop in stops {
        let sb = stop.as_bytes();
        if p.rest().starts_with(sb) {
            let next = p.peek_at(sb.len()).unwrap_or(0);
            let is_kw = !ic(next) || matches!(*stop, "}" | ")" | ";;" | ";;;" | ";&" | ";;&");
            if is_kw { return true; }
        }
    }
    false
}

fn read_word(p: &mut Parser) -> String {
    let start = p.pos;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if ic(c) { p.pos += 1; } else { break; }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn peek_word(p: &Parser) -> &str {
    let mut i = p.pos;
    while i < p.input.len() && ic(p.input[i]) { i += 1; }
    std::str::from_utf8(&p.input[p.pos..i]).unwrap_or("")
}

// Keywords that start compound commands
fn is_compound_kw(s: &str) -> bool {
    matches!(s, "if" | "while" | "until" | "for" | "select" | "case" | "function")
}

// Keywords used as assignment builtins (context where name=value is assignment not arg)
fn is_assign_builtin(s: &str) -> bool {
    matches!(s, "export" | "local" | "declare" | "readonly")
}

fn parse_statement(p: &mut Parser, segs: &mut Vec<Seg>, stops: &[&str]) {
    if p.pos >= p.len() { return; }

    // Check for stop tokens
    if at_stop(p, stops) { return; }

    let c = p.input[p.pos];

    // Comments
    if c == b'#' {
        let start = p.pos;
        while p.pos < p.len() && p.input[p.pos] != b'\n' { p.pos += 1; }
        let comment = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        segs.push(Seg::Comment(comment));
        return;
    }

    // Try compound commands
    let word = peek_word(p);
    if is_compound_kw(word) || word == "{" || word == "(" {
        parse_compound(p, segs, stops);
        return;
    }

    // Check for function definition: name() { ... } or name () { ... }
    if looks_like_func_def(p) {
        parse_func_def(p, segs);
        return;
    }

    // Simple command
    parse_simple_cmd(p, segs, stops);
}

fn looks_like_func_def(p: &Parser) -> bool {
    let mut i = p.pos;
    if i >= p.input.len() || !is_start(p.input[i]) { return false; }
    while i < p.input.len() && ic(p.input[i]) { i += 1; }
    while i < p.input.len() && p.input[i] == b' ' { i += 1; }
    if i >= p.input.len() || p.input[i] != b'(' { return false; }
    i += 1;
    while i < p.input.len() && p.input[i] == b' ' { i += 1; }
    i < p.input.len() && p.input[i] == b')'
}

fn parse_compound(p: &mut Parser, segs: &mut Vec<Seg>, _stops: &[&str]) {
    let word = peek_word(p);
    match word {
        "if" => parse_if(p, segs),
        "while" | "until" => parse_while_until(p, segs),
        "for" => parse_for(p, segs),
        "select" => parse_select(p, segs),
        "case" => parse_case(p, segs),
        "function" => parse_function_kw(p, segs),
        "{" => parse_brace_group(p, segs),
        "(" => parse_subshell(p, segs),
        _ => {}
    }
}

fn emit_kw(p: &mut Parser, segs: &mut Vec<Seg>, kw: &str) {
    // emit keyword and consume it from input
    assert!(p.rest().starts_with(kw.as_bytes()));
    p.pos += kw.len();
    segs.push(Seg::Kw(kw.to_string()));
}

fn try_emit_kw(p: &mut Parser, segs: &mut Vec<Seg>, kw: &str) -> bool {
    if p.rest().starts_with(kw.as_bytes()) {
        let next = p.peek_at(kw.len()).unwrap_or(0);
        if !ic(next) || matches!(kw, "}" | ")" | ";;" | ";;;" | ";&") {
            p.pos += kw.len();
            segs.push(Seg::Kw(kw.to_string()));
            return true;
        }
    }
    false
}

fn parse_stmts_until(p: &mut Parser, segs: &mut Vec<Seg>, stops: &[&str]) {
    loop {
        skip_ws(p, segs);
        if p.pos >= p.len() { break; }
        if at_stop(p, stops) { break; }
        let start = p.pos;
        parse_statement(p, segs, stops);
        if p.pos == start {
            let c = p.advance().unwrap_or(b'\n');
            push_verb(segs, &[c]);
        }
        // After statement, collect separators
        collect_seps(p, segs);
    }
}

fn collect_seps(p: &mut Parser, segs: &mut Vec<Seg>) {
    while p.pos < p.len() {
        if p.starts_with(b"&&") || p.starts_with(b"||") {
            push_verb(segs, &p.input[p.pos..p.pos+2]);
            p.pos += 2;
            skip_ws(p, segs);
        } else if p.starts_with(b"|&") {
            push_verb(segs, &p.input[p.pos..p.pos+2]);
            p.pos += 2;
            skip_ws(p, segs);
        } else if p.peek() == Some(b'|') && p.peek_at(1) != Some(b'|') {
            push_verb(segs, b"|");
            p.pos += 1;
            skip_ws(p, segs);
        } else if p.peek() == Some(b';') {
            push_verb(segs, b";");
            p.pos += 1;
            skip_ws(p, segs);
            break; // One statement done
        } else if p.peek() == Some(b'&') && p.peek_at(1) != Some(b'&') {
            push_verb(segs, b"&");
            p.pos += 1;
            skip_ws(p, segs);
            break;
        } else {
            break;
        }
    }
}

fn parse_if(p: &mut Parser, segs: &mut Vec<Seg>) {
    segs.push(Seg::Kw("if ".to_string())); p.pos += 2;
    skip_ws(p, segs);
    parse_stmts_until(p, segs, &["then"]);
    skip_ws(p, segs);
    if try_emit_kw(p, segs, "then") {
        loop {
            skip_ws(p, segs);
            if p.pos >= p.len() { break; }
            if at_stop(p, &["elif", "else", "fi"]) {
                if p.rest().starts_with(b"elif") && !ic(p.peek_at(4).unwrap_or(0)) {
                    segs.push(Seg::Kw("elif ".to_string())); p.pos += 4;
                    skip_ws(p, segs);
                    parse_stmts_until(p, segs, &["then"]);
                    skip_ws(p, segs);
                    try_emit_kw(p, segs, "then");
                } else if p.rest().starts_with(b"else") && !ic(p.peek_at(4).unwrap_or(0)) {
                    try_emit_kw(p, segs, "else");
                    skip_ws(p, segs);
                    parse_stmts_until(p, segs, &["fi"]);
                    skip_ws(p, segs);
                    try_emit_kw(p, segs, "fi");
                    break;
                } else if p.rest().starts_with(b"fi") && !ic(p.peek_at(2).unwrap_or(0)) {
                    try_emit_kw(p, segs, "fi");
                    break;
                } else {
                    break;
                }
            } else {
                let start = p.pos;
                parse_statement(p, segs, &["elif", "else", "fi"]);
                if p.pos == start { let c = p.advance().unwrap_or(b'\n'); push_verb(segs, &[c]); }
                collect_seps(p, segs);
            }
        }
    }
}

fn parse_while_until(p: &mut Parser, segs: &mut Vec<Seg>) {
    let kw = read_word(p);
    segs.push(Seg::Kw(format!("{} ", kw)));
    skip_ws(p, segs);
    parse_stmts_until(p, segs, &["do"]);
    skip_ws(p, segs);
    if try_emit_kw(p, segs, "do") {
        skip_ws(p, segs);
        parse_stmts_until(p, segs, &["done"]);
        skip_ws(p, segs);
        try_emit_kw(p, segs, "done");
    }
}

fn parse_for(p: &mut Parser, segs: &mut Vec<Seg>) {
    p.pos += 3; // consume "for"
    skip_inline_ws(p, segs);

    // Check for C-style: for ((
    if p.starts_with(b"((") {
        segs.push(Seg::Kw("for".to_string()));
        // parse ((...)) as arithmetic
        let arith = parse_arith_expansion(p);
        segs.push(Seg::Arith(arith));
        skip_ws(p, segs);
        collect_seps_simple(p, segs);
        skip_ws(p, segs);
        if try_emit_kw(p, segs, "do") {
            skip_ws(p, segs);
            parse_stmts_until(p, segs, &["done"]);
            skip_ws(p, segs);
            try_emit_kw(p, segs, "done");
        }
        return;
    }

    // Regular for: for var in items; do body done
    let var_start = p.pos;
    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let var_name = String::from_utf8_lossy(&p.input[var_start..p.pos]).to_string();

    segs.push(Seg::Kw("for ".to_string()));
    // Emit var name as assign-lhs (just the name, no =)
    segs.push(Seg::AssignLhs(format!("{}=", var_name)));
    // Fix: we used AssignLhs with "=" but for loop var has no "="
    // Let me reconsider - AssignLhs renders "name" in bright blue and "=" as plain
    // For the for-loop variable, we want: COLOR_ASSIGN "varname" RESET " " COLOR_KW "in" RESET
    // So AssignLhs("varname=") would render: [bright_blue]varname[reset]=  
    // But we want: [bright_blue]varname[reset] [bold]in[reset]
    // The "=" would be in the next part. Let me fix this:
    if let Some(Seg::AssignLhs(ref mut s)) = segs.last_mut() {
        *s = var_name.clone(); // remove the "="
    }
    segs.push(Seg::Kw(" ".to_string()));

    skip_inline_ws(p, segs);

    if p.rest().starts_with(b"in") && !ic(p.peek_at(2).unwrap_or(0)) {
        p.pos += 2;
        segs.push(Seg::Kw("in".to_string()));
    }

    skip_inline_ws(p, segs);

    // Parse items with for-loop transform
    parse_for_items(p, segs);

    skip_ws(p, segs);
    collect_seps_simple(p, segs);
    skip_ws(p, segs);

    if try_emit_kw(p, segs, "do") {
        skip_ws(p, segs);
        parse_stmts_until(p, segs, &["done"]);
        skip_ws(p, segs);
        try_emit_kw(p, segs, "done");
    }
}

fn collect_seps_simple(p: &mut Parser, segs: &mut Vec<Seg>) {
    if p.peek() == Some(b';') { push_verb(segs, b";"); p.pos += 1; }
}

fn parse_for_items(p: &mut Parser, segs: &mut Vec<Seg>) {
    // Parse items in "for var in ITEMS" context
    // Each item that is an unquoted $var needs to become "${var[@]}"
    // Each unquoted $() needs to become "$(...)
    loop {
        skip_inline_ws(p, segs);
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b';' || c == b'\n' || c == b'\r' { break; }
        if p.rest().starts_with(b"do") && !ic(p.peek_at(2).unwrap_or(0)) { break; }

        // Parse one word in for-in context
        parse_word_in_for(p, segs);
    }
}

fn parse_word_in_for(p: &mut Parser, segs: &mut Vec<Seg>) {
    if p.pos >= p.len() { return; }
    let c = p.input[p.pos];
    match c {
        b'"' => { let dq = parse_dq(p); segs.push(dq); }
        b'\'' => { let sq = parse_sq(p); segs.push(sq); }
        b'$' => {
            // In for-in context, $var -> "${var[@]}", $() -> "$(...)"
            let seg = parse_dollar_in_for(p);
            segs.push(seg);
        }
        b'`' => {
            // backtick -> need to wrap in quotes
            let inner = parse_backtick_inner(p);
            segs.push(Seg::NeedQuote("$(`".to_string(), inner, "`".to_string()));
        }
        _ => {
            // Plain word
            let w = read_plain_word_for(p);
            push_verb_str(segs, &w);
        }
    }
}

fn read_plain_word_for(p: &mut Parser) -> String {
    let start = p.pos;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == b';' { break; }
        if c == b'"' || c == b'\'' || c == b'$' || c == b'`' { break; }
        if p.rest().starts_with(b"do") && !ic(p.peek_at(2).unwrap_or(0)) { break; }
        p.pos += 1;
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_dollar_in_for(p: &mut Parser) -> Seg {
    // We're in for-in context: unquoted $var becomes "${var[@]}"
    assert_eq!(p.peek(), Some(b'$'));

    // Check for $@ and $*
    if p.peek_at(1) == Some(b'@') {
        p.pos += 2;
        return Seg::UVar("$@".to_string(), "\"$@\"".to_string());
    }
    if p.peek_at(1) == Some(b'*') {
        p.pos += 2;
        return Seg::UVar("$*".to_string(), "\"$@\"".to_string());
    }

    // Check for $?$$$!$#
    if let Some(c) = p.peek_at(1) {
        if c == b'?' || c == b'$' || c == b'!' || c == b'#' {
            p.pos += 2;
            return Seg::UVar(format!("${}", c as char), format!("\"${}\"", c as char));
        }
    }

    // Check for $( - command substitution
    if p.peek_at(1) == Some(b'(') {
        if p.peek_at(2) == Some(b'(') {
            // $((...)) arithmetic - safe but needs quoting in for-in
            let s = parse_arith_expansion_dollar(p);
            return Seg::NeedQuote(s, vec![], "".to_string());
        }
        // $(...) cmd sub
        p.pos += 2; // skip $(
        let inner = parse_cmd_sub_inner(p);
        if p.peek() == Some(b')') { p.pos += 1; }
        return Seg::NeedQuote("$(".to_string(), inner, ")".to_string());
    }

    // Check for ${...}
    if p.peek_at(1) == Some(b'{') {
        let (orig, trans) = parse_dollar_brace_for(p);
        return Seg::UVar(orig, trans);
    }

    // Check for $1-$9 (positional params)
    if let Some(c) = p.peek_at(1) {
        if c.is_ascii_digit() {
            if let Some(c2) = p.peek_at(2) {
                if c2.is_ascii_digit() {
                    // Multi-digit positional param without braces: pitfall!
                    // We handle this in the regular command context
                    // In for-in, same treatment: it's a pitfall, but just quote it
                    p.pos += 2; // only consume $N
                    let orig = format!("${}", c as char);
                    let trans = format!("\"${}\"", c as char);
                    return Seg::UVar(orig, trans);
                }
            }
            p.pos += 2;
            let orig = format!("${}", c as char);
            let trans = format!("\"${}\"", c as char);
            return Seg::UVar(orig, trans);
        }
    }

    // Regular $identifier - in for-in becomes "${ident[@]}"
    p.pos += 1; // skip $
    let start = p.pos;
    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
    if name.is_empty() {
        return Seg::Verbatim("$".to_string());
    }
    let orig = format!("${}", name);
    let trans = format!("\"${{{name}[@]}}\"");
    Seg::UVar(orig, trans)
}

fn parse_dollar_brace_for(p: &mut Parser) -> (String, String) {
    // ${...} in for-in context
    let start = p.pos;
    p.pos += 2; // skip ${
    let (name, suffix) = read_brace_var_content(p);
    if p.peek() == Some(b'}') { p.pos += 1; }
    let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    // Determine transformation
    if suffix.is_empty() {
        // ${var} -> "${var[@]}"
        let trans = format!("\"${{{name}[@]}}\"");
        (orig, trans)
    } else if suffix == "[@]" || suffix == "[*]" || suffix.starts_with("[@]") {
        // ${var[@]} -> "${var[@]}"
        let trans = format!("\"${{{name}[@]}}\"");
        (orig, trans)
    } else {
        // Complex expansion - just add quotes
        let trans = format!("\"{}\"", orig);
        (orig, trans)
    }
}

fn read_brace_var_content(p: &mut Parser) -> (String, String) {
    // Read the variable name and optional subscript/modifier
    let name_start = p.pos;
    // Skip special chars: # ! @ * etc.
    if p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'#' || c == b'!' || c == b'@' || c == b'*' {
            p.pos += 1;
        }
    }
    let ident_start = p.pos;
    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[ident_start..p.pos]).to_string();

    // Read suffix (subscript, operator, etc.)
    let suf_start = p.pos;
    // Collect until matching }
    let mut depth = 1i32;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'{' { depth += 1; p.pos += 1; }
        else if c == b'}' {
            depth -= 1;
            if depth == 0 { break; }
            p.pos += 1;
        } else if c == b'\'' {
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'\'' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else if c == b'"' {
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'"' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else {
            p.pos += 1;
        }
    }
    let suffix = String::from_utf8_lossy(&p.input[suf_start..p.pos]).to_string();
    (name, suffix)
}

