fn parse_cmd_name(p: &mut Parser, segs: &mut Vec<Seg>) -> String {
    // Parse the command name - could be a variable, string, etc.
    if p.pos >= p.len() { return String::new(); }

    // Check for [[ ]]
    if p.starts_with(b"[[") {
        return parse_double_bracket(p, segs);
    }

    // Check for [ (test command)
    if p.peek() == Some(b'[') && p.peek_at(1) != Some(b'[') {
        return parse_bracket_test(p, segs);
    }

    let c = p.input[p.pos];

    // Command could start with $var (variable as command)
    if c == b'$' {
        let word = parse_dollar_as_cmd(p);
        segs.push(word);
        return String::new();
    }

    // Plain command name
    let start = p.pos;
    // Read the command word (could include various chars)
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { break; }
        if c == b';' || c == b'&' || c == b'|' || c == b'<' || c == b'>' { break; }
        if c == b'"' || c == b'\'' || c == b'`' { break; }
        if c == b'(' { break; }
        if c == b'$' { break; }
        p.pos += 1;
    }
    let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    if is_keyword(&name) {
        segs.push(Seg::Kw(name.clone()));
    } else if !name.is_empty() {
