        while p.pos < p.input.len() && p.input[p.pos] != b'\n' { p.pos += 1; }
        if p.peek() == Some(b'\n') { p.pos += 1; }
    }

    // Reached EOF before delimiter
    let remaining = String::from_utf8_lossy(&p.input[content_start..p.pos]).to_string();
    segs.push(Seg::Heredoc(format!("{}{}{}", op_str, delim_str, remaining)));
    true
}

