        push_verb(segs, b"&>>"); p.pos += 3;
        skip_inline_ws(p, segs);
        parse_arg_word(p, segs, false);
        return true;
    }
    if p.starts_with(b"&>") {
        push_verb(segs, b"&>"); p.pos += 2;
        skip_inline_ws(p, segs);
        parse_arg_word(p, segs, false);
        return true;
    }

    false
}

fn parse_heredoc_redirect(p: &mut Parser, segs: &mut Vec<Seg>, op_start: usize, strip: bool) -> bool {
    // We consumed "<<" or "<<-" already, now need to read the delimiter
    let op_end = p.pos;
    skip_inline_ws(p, segs);

    // Read the heredoc delimiter (could be quoted)
    let mut quoted = false;
    let delim_start = p.pos;
    let raw_delim;

    if p.peek() == Some(b'\'') {
        // Quoted delimiter - no expansion in heredoc
        quoted = true;
        p.pos += 1;
        let start = p.pos;
        while p.pos < p.input.len() && p.input[p.pos] != b'\'' { p.pos += 1; }
        raw_delim = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        if p.peek() == Some(b'\'') { p.pos += 1; }
    } else if p.peek() == Some(b'"') {
        p.pos += 1;
        let start = p.pos;
        while p.pos < p.input.len() && p.input[p.pos] != b'"' { p.pos += 1; }
        raw_delim = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        if p.peek() == Some(b'"') { p.pos += 1; }
    } else {
        // Unquoted delimiter
        let start = p.pos;
        while p.pos < p.input.len() {
            let c = p.input[p.pos];
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == b';' { break; }
            if c == b'\\' && p.peek_at(1) == Some(b'\n') { break; }
            p.pos += 1;
        }
        raw_delim = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
    }

    let delim_end = p.pos;

    // Build the heredoc header
    let op_str = String::from_utf8_lossy(&p.input[op_start..op_end]).to_string();
    let delim_str = String::from_utf8_lossy(&p.input[delim_start..delim_end]).to_string();

    // Now find the heredoc content (after the current line)
    // Skip rest of current line
    while p.pos < p.input.len() && p.input[p.pos] != b'\n' { p.pos += 1; }
    if p.peek() == Some(b'\n') { p.pos += 1; }

    // Read heredoc content until we find the delimiter on its own line
    let content_start = p.pos;
    loop {
        if p.pos >= p.input.len() { break; }
        let line_start = p.pos;
        // Skip tabs if strip mode
        if strip {
            while p.pos < p.input.len() && p.input[p.pos] == b'\t' { p.pos += 1; }
        }
        // Check if this line is the delimiter
        let dl = raw_delim.as_bytes();
        if p.input[p.pos..].starts_with(dl) {
            let after = p.pos + dl.len();
            let end_ok = after >= p.input.len() || p.input[after] == b'\n';
            if end_ok {
                let content = String::from_utf8_lossy(&p.input[content_start..line_start]).to_string();
                let close_start = p.pos;
                p.pos += dl.len();
                if p.peek() == Some(b'\n') { p.pos += 1; }
                let close = String::from_utf8_lossy(&p.input[close_start..p.pos]).to_string();

                let full_heredoc = format!("{}{}{}{}{}", op_str, delim_str, "\n", content, close);
                segs.push(Seg::Heredoc(full_heredoc));
                return true;
            }
        }
        // Skip to end of line
        p.pos = line_start;
        while p.pos < p.input.len() && p.input[p.pos] != b'\n' { p.pos += 1; }
        if p.peek() == Some(b'\n') { p.pos += 1; }
    }

    // Reached EOF before delimiter
    let remaining = String::from_utf8_lossy(&p.input[content_start..p.pos]).to_string();
    segs.push(Seg::Heredoc(format!("{}{}{}", op_str, delim_str, remaining)));
    true
}

