fn parse_arg_word(p: &mut Parser, segs: &mut Vec<Seg>, in_test: bool) {
    // Parse a word in command argument position
    // Unquoted $var needs quoting

    if p.pos >= p.len() { return; }

    // Collect a "word" which may be multiple adjacent quoted/unquoted parts
    let mut word_segs: Vec<Seg> = Vec::new();

    loop {
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];

        // Word terminators
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { break; }
        if c == b';' || c == b'&' || c == b'|' { break; }
        if c == b')' && !in_test { break; } // end of subshell
        if c == b']' && in_test { break; }

        match c {
            b'"' => {
                let dq = parse_dq(p);
                word_segs.push(dq);
