                    p.pos += 2;
                    skip_inline_ws(p, segs);
                    continue;
                }
                let start = p.pos;
                p.pos += 2; // skip backslash and next char
                let text = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                if let Some(Seg::Verbatim(ref mut prev)) = word_segs.last_mut() {
                    prev.push_str(&text);
                } else {
                    word_segs.push(Seg::Verbatim(text));
                }
            }
            _ => {
                let start = p.pos;
                while p.pos < p.len() {
                    let c = p.input[p.pos];
                    if c == b'"' || c == b'\'' || c == b'$' || c == b'`' || c == b'\\' { break; }
                    if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { break; }
                    if c == b';' || c == b'|' || c == b'&' { break; }
                    if c == b')' && !in_test { break; }
                    if c == b']' && in_test { break; }
                    if c == b'<' || c == b'>' { break; }
                    p.pos += 1;
                }
                let text = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                if let Some(Seg::Verbatim(ref mut prev)) = word_segs.last_mut() {
                    prev.push_str(&text);
                } else {
                    word_segs.push(Seg::Verbatim(text));
                }
            }
        }
    }

    // Merge adjacent word segments
    merge_word_segs(word_segs, segs);
}

fn has_unsafe_vars(segs: &[Seg]) -> bool {
    for s in segs {
        match s {
            Seg::UVar(_, _) => return true,
            Seg::NeedQuote(_, inner, _) => if has_unsafe_vars(inner) { return true; }
            _ => {}
        }
    }
    false
}

fn merge_word_segs(mut word_segs: Vec<Seg>, segs: &mut Vec<Seg>) {
    // Handle concatenation of adjacent unquoted segments
    // The key rules:
    // 1. If there are any UnsafeVar segments, we need to wrap them in quotes
    // 2. Adjacent text+UnsafeVar or UnsafeVar+text may need to be merged into one DQ string

    if word_segs.is_empty() { return; }

    // Check if there are any unsafe vars or NeedQuote items
    let has_unsafe = word_segs.iter().any(|s| matches!(s, Seg::UVar(_, _) | Seg::NeedQuote(_, _, _)));

    if !has_unsafe {
        // No unsafe vars - just output everything as-is
        segs.extend(word_segs);
        return;
    }

    // We need to merge and quote things
    // Strategy: collect runs of unsafe/text into double-quoted strings

    // Simple case: single UnsafeVar
    if word_segs.len() == 1 {
        segs.extend(word_segs);
        return;
    }

    // Multiple segments - need careful merging
    // Group consecutive text+var into DQ strings
    let mut merged = merge_to_dq_if_needed(word_segs);
    segs.extend(merged);
}

fn merge_to_dq_if_needed(word_segs: Vec<Seg>) -> Vec<Seg> {
