fn parse_dollar_expr(p: &mut Parser, in_test: bool) -> Seg {
    assert_eq!(p.peek(), Some(b'$'));

    // Check what follows $
    let c2 = p.peek_at(1).unwrap_or(0);

    match c2 {
        b'(' => {
            if p.peek_at(2) == Some(b'(') {
                // $((...)) arithmetic
                let s = parse_arith_expansion_dollar(p);
                Seg::Arith(s)
            } else {
                // $(...) command substitution
                p.pos += 2; // skip $(
                let inner = parse_cmd_sub_inner(p);
                if p.peek() == Some(b')') { p.pos += 1; }
                // This needs quoting when in command position
                Seg::NeedQuote("$(".to_string(), inner, ")".to_string())
            }
        }
        b'{' => {
            // ${...}
            parse_dollar_brace(p, in_test)
        }
        b'@' => {
            p.pos += 2;
            Seg::UVar("$@".to_string(), "\"$@\"".to_string())
        }
        b'*' => {
            p.pos += 2;
            Seg::UVar("$*".to_string(), "\"$@\"".to_string())
        }
        b'?' | b'$' | b'!' | b'#' => {
            p.pos += 2;
            Seg::SafeVar(format!("${}", c2 as char))
        }
        b'\'' => {
            // $'...' ANSI C string
            p.pos += 1; // skip $
            let sq = parse_sq(p);
            sq
        }
        _ if c2.is_ascii_digit() => {
            // Positional parameter or multi-digit
            p.pos += 2;
            let name = format!("${}", c2 as char);
            // Check for multi-digit pitfall
            if let Some(c3) = p.peek() {
                if c3.is_ascii_digit() {
                    // This is a pitfall: $12 etc.
                    // Emit what we have, report error
                    let fname = p.filename.as_deref().unwrap_or("stdin");
                    // Find the line
                    let line = find_line_at(p, p.pos - 2);
                    let col = line.1;
                    eprintln!("{}: Unsupported syntax: Syntactic pitfall", fname);
                    eprintln!("{}", line.0);
                    eprintln!("{}^^^", " ".repeat(col));
                    eprintln!("This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.");
                    eprintln!("");
                    eprintln!("Try this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j");
                    eprintln!("");
                    eprintln!("Here is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".");
                    eprintln!("");
                    eprintln!("Syntactic pitfalls are deemed too dangerous to fix automatically");
                    eprintln!("(the purpose of Shellharden is to fix vulnerable code \u{2013} code that mostly does what it looks like, as opposed to code that never does what it looks like):");
                    eprintln!("* Fixing what it does would be 100% subtle and might slip through code review unnoticed.");
                    eprintln!("* Fixing its look would make a likely bug look intentional.");
                    p.had_error = true;
                    return Seg::Verbatim(name);
                }
            }
            Seg::UVar(name.clone(), format!("\"{}\"", name))
        }
        _ if is_start(c2) => {
            // Regular $identifier
            p.pos += 1; // skip $
            let start = p.pos;
            while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
            let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
            let orig = format!("${}", name);
            let trans = format!("\"${}\"", name);
            Seg::UVar(orig, trans)
        }
        _ => {
            // Just a $ sign
            p.pos += 1;
            Seg::Verbatim("$".to_string())
        }
    }
}

fn find_line_at(p: &Parser, pos: usize) -> (String, usize) {
    // Find the line containing 'pos' and the column
    let mut line_start = 0;
    for (i, &c) in p.input[..pos].iter().enumerate() {
        if c == b'\n' { line_start = i + 1; }
    }
    let line_end = p.input[line_start..].iter().position(|&c| c == b'\n')
        .map(|i| line_start + i)
        .unwrap_or(p.input.len());
    let line = String::from_utf8_lossy(&p.input[line_start..line_end]).to_string();
    let col = pos - line_start;
    (line, col)
}

fn parse_dollar_brace(p: &mut Parser, in_test: bool) -> Seg {
    let start = p.pos;
    p.pos += 2; // skip ${

    // Check what's inside
    let peek = p.peek().unwrap_or(0);

    // Handle special vars: ${#}, ${!}, ${@}, ${*}, ${?}, ${$}
    if peek == b'#' && (p.peek_at(1) == Some(b'}') || !is_start(p.peek_at(1).unwrap_or(0))) {
        // Length or $#
        // Read the rest
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    if matches!(peek, b'!' | b'@' | b'*' | b'?' | b'$') && p.peek_at(1) == Some(b'}') {
        p.pos += 2; // skip X}
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        if peek == b'@' || peek == b'*' {
            // ${@} -> "${@}", ${*} -> "${*}"
            let trans = format!("\"{}\"", orig);
            return Seg::UVar(orig, trans);
        }
        return Seg::SafeVar(orig);
    }

    // Handle ${!prefix*} and ${!prefix@} indirect
    if peek == b'!' {
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    // Handle ${#var} - length
    if peek == b'#' {
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    // Regular variable: ${varname}, ${varname[@]}, ${varname:-default}, etc.
    // Read variable name
    let name_start = p.pos;
    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[name_start..p.pos]).to_string();

    // Read the rest until }
    let suffix_start = p.pos;
    let mut depth = 1i32;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'{' { depth += 1; p.pos += 1; }
        else if c == b'}' {
            depth -= 1;
            if depth == 0 { p.pos += 1; break; }
            p.pos += 1;
        } else if c == b'\'' {
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'\'' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else {
            p.pos += 1;
        }
    }
    let suffix = String::from_utf8_lossy(&p.input[suffix_start..p.pos-1]).to_string();
    let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    // Determine if this needs quoting and what the transform is
    // ${var} alone -> needs quoting, becomes "$var" (braces removed) in transform
    // ${var[@]}, ${var[*]}, ${var:-...}, etc -> needs quoting, keeps as-is
    // ${#var} -> safe (length)
    // ${!var} -> safe (indirect name expansion)

    if name.is_empty() {
        // Positional or special
        return Seg::SafeVar(orig);
    }

    // Check suffix to determine transformation
    let trans = if suffix.is_empty() {
        // "${varname}" - simple var with braces
        // In command position, needs quoting. Braces unnecessary.
        format!("\"{}\"", orig) // will be rendered as "$varname" when braces removed
    } else if suffix == "[@]" || suffix == "[*]" {
        // ${var[@]} or ${var[*]}
        if suffix == "[*]" {
            // ${var[*]} -> "${var[@]}"
            format!("\"${{{name}[@]}}\"")
        } else {
            format!("\"{}\"", orig)
        }
    } else {
        // Complex expansion: ${var:-default}, ${var/pat/rep}, etc.
        format!("\"{}\"", orig)
    };

    Seg::UVar(orig, trans)
}

fn parse_arith_expansion(p: &mut Parser) -> String {
    // Parse ((...)) or $((...))
    let start = p.pos;
    assert!(p.starts_with(b"(("));
    p.pos += 2;
    let mut depth = 1u32;
    while p.pos < p.len() {
        if p.starts_with(b"((") { depth += 1; p.pos += 2; }
        else if p.starts_with(b"))") {
            depth -= 1; p.pos += 2;
            if depth == 0 { break; }
        } else {
            p.pos += 1;
        }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_arith_expansion_dollar(p: &mut Parser) -> String {
    // Parse $((...)): starts at $
    assert!(p.starts_with(b"$(("));
    let start = p.pos;
    p.pos += 3; // skip $((
    let mut depth = 1u32;
    while p.pos < p.len() {
        if p.starts_with(b"((") { depth += 1; p.pos += 2; }
        else if p.starts_with(b"))") {
            depth -= 1; p.pos += 2;
            if depth == 0 { break; }
        } else {
            p.pos += 1;
        }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_cmd_sub_inner(p: &mut Parser) -> Vec<Seg> {
    // Parse the inside of $(...)
    let mut inner = Vec::new();
    parse_stmts_until_close(p, &mut inner);
    inner
}

fn parse_stmts_until_close(p: &mut Parser, segs: &mut Vec<Seg>) {
    // Parse statements until we hit ) or end
    let mut depth = 1i32;
    loop {
        skip_ws(p, segs);
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b')' { break; } // will be consumed by caller

        let start = p.pos;
        // Parse one statement
        parse_statement(p, segs, &[")"]);
        collect_seps(p, segs);

        if p.pos == start {
            let c = p.advance().unwrap_or(b')');
            if c == b')' { p.pos -= 1; break; }
            push_verb(segs, &[c]);
        }
