fn parse_backtick_inner(p: &mut Parser) -> Vec<Seg> {
    assert_eq!(p.peek(), Some(b'`'));
    p.pos += 1; // skip opening `
    let mut inner = Vec::new();
    loop {
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b'`' { p.pos += 1; break; }
        let start = p.pos;
        parse_statement(p, &mut inner, &[]);
        if p.pos == start {
            // No progress - check for ` terminator
            if p.peek() == Some(b'`') { p.pos += 1; break; }
            let c = p.advance().unwrap_or(b'`');
            push_verb(&mut inner, &[c]);
        }
        // collect separators
        collect_seps(p, &mut inner);
    }
    inner
}

fn parse_dq(p: &mut Parser) -> Seg {
    assert_eq!(p.peek(), Some(b'"'));
    p.pos += 1; // skip "

    let mut parts: Vec<DQSeg> = Vec::new();
    let mut lit = String::new();

    loop {
        if p.pos >= p.len() {
            // Unclosed string
            if !lit.is_empty() { parts.push(DQSeg::Lit(lit)); }
            break;
        }
        let c = p.input[p.pos];
        match c {
            b'"' => { p.pos += 1; break; }
            b'\\' => {
                // Escape sequence inside double quotes
                let nc = p.peek_at(1).unwrap_or(0);
                if nc == b'"' || nc == b'\\' || nc == b'$' || nc == b'`' || nc == b'\n' {
                    lit.push(c as char);
                    lit.push(nc as char);
                    p.pos += 2;
                } else {
                    lit.push(c as char);
                    p.pos += 1;
                }
            }
            b'$' => {
                if !lit.is_empty() { parts.push(DQSeg::Lit(lit.clone())); lit.clear(); }
                let c2 = p.peek_at(1).unwrap_or(0);
                match c2 {
                    b'(' => {
                        if p.peek_at(2) == Some(b'(') {
                            // $((...))
                            let arith = parse_arith_expansion_dollar(p);
                            parts.push(DQSeg::Arith(arith));
