            Seg::UVar(name.clone(), format!("\"{}\"", name))
        }
        _ if is_start(c2) => {
            // Regular $identifier
            p.pos += 1; // skip $
            let start = p.pos;
            while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
            let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
            let orig = format!("${}", name);
            let trans = format!("\"${}\"", name);
            Seg::UVar(orig, trans)
        }
        _ => {
            // Just a $ sign
            p.pos += 1;
            Seg::Verbatim("$".to_string())
        }
    }
}

fn find_line_at(p: &Parser, pos: usize) -> (String, usize) {
    // Find the line containing 'pos' and the column
    let mut line_start = 0;
    for (i, &c) in p.input[..pos].iter().enumerate() {
        if c == b'\n' { line_start = i + 1; }
    }
    let line_end = p.input[line_start..].iter().position(|&c| c == b'\n')
        .map(|i| line_start + i)
        .unwrap_or(p.input.len());
    let line = String::from_utf8_lossy(&p.input[line_start..line_end]).to_string();
    let col = pos - line_start;
    (line, col)
}

fn parse_dollar_brace(p: &mut Parser, in_test: bool) -> Seg {
    let start = p.pos;
    p.pos += 2; // skip ${

    // Check what's inside
    let peek = p.peek().unwrap_or(0);

    // Handle special vars: ${#}, ${!}, ${@}, ${*}, ${?}, ${$}
    if peek == b'#' && (p.peek_at(1) == Some(b'}') || !is_start(p.peek_at(1).unwrap_or(0))) {
        // Length or $#
        // Read the rest
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    if matches!(peek, b'!' | b'@' | b'*' | b'?' | b'$') && p.peek_at(1) == Some(b'}') {
        p.pos += 2; // skip X}
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        if peek == b'@' || peek == b'*' {
            // ${@} -> "${@}", ${*} -> "${*}"
            let trans = format!("\"{}\"", orig);
            return Seg::UVar(orig, trans);
        }
        return Seg::SafeVar(orig);
    }

    // Handle ${!prefix*} and ${!prefix@} indirect
    if peek == b'!' {
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    // Handle ${#var} - length
    if peek == b'#' {
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    // Regular variable: ${varname}, ${varname[@]}, ${varname:-default}, etc.
    // Read variable name
    let name_start = p.pos;
    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[name_start..p.pos]).to_string();

    // Read the rest until }
    let suffix_start = p.pos;
    let mut depth = 1i32;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'{' { depth += 1; p.pos += 1; }
        else if c == b'}' {
            depth -= 1;
            if depth == 0 { p.pos += 1; break; }
            p.pos += 1;
        } else if c == b'\'' {
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'\'' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else {
            p.pos += 1;
        }
    }
    let suffix = String::from_utf8_lossy(&p.input[suffix_start..p.pos-1]).to_string();
    let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    // Determine if this needs quoting and what the transform is
    // ${var} alone -> needs quoting, becomes "$var" (braces removed) in transform
    // ${var[@]}, ${var[*]}, ${var:-...}, etc -> needs quoting, keeps as-is
    // ${#var} -> safe (length)
    // ${!var} -> safe (indirect name expansion)

    if name.is_empty() {
        // Positional or special
        return Seg::SafeVar(orig);
    }

    // Check suffix to determine transformation
    let trans = if suffix.is_empty() {
        // "${varname}" - simple var with braces
        // In command position, needs quoting. Braces unnecessary.
        format!("\"{}\"", orig) // will be rendered as "$varname" when braces removed
    } else if suffix == "[@]" || suffix == "[*]" {
        // ${var[@]} or ${var[*]}
        if suffix == "[*]" {
            // ${var[*]} -> "${var[@]}"
            format!("\"${{{name}[@]}}\"")
        } else {
            format!("\"{}\"", orig)
        }
    } else {
        // Complex expansion: ${var:-default}, ${var/pat/rep}, etc.
        format!("\"{}\"", orig)
    };

    Seg::UVar(orig, trans)
}

fn parse_arith_expansion(p: &mut Parser) -> String {
    // Parse ((...)) or $((...))
    let start = p.pos;
    assert!(p.starts_with(b"(("));
    p.pos += 2;
    let mut depth = 1u32;
    while p.pos < p.len() {
        if p.starts_with(b"((") { depth += 1; p.pos += 2; }
        else if p.starts_with(b"))") {
            depth -= 1; p.pos += 2;
            if depth == 0 { break; }
        } else {
            p.pos += 1;
        }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_arith_expansion_dollar(p: &mut Parser) -> String {
    // Parse $((...)): starts at $
    assert!(p.starts_with(b"$(("));
    let start = p.pos;
    p.pos += 3; // skip $((
    let mut depth = 1u32;
    while p.pos < p.len() {
        if p.starts_with(b"((") { depth += 1; p.pos += 2; }
        else if p.starts_with(b"))") {
            depth -= 1; p.pos += 2;
            if depth == 0 { break; }
        } else {
            p.pos += 1;
        }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_cmd_sub_inner(p: &mut Parser) -> Vec<Seg> {
    // Parse the inside of $(...)
    let mut inner = Vec::new();
    parse_stmts_until_close(p, &mut inner);
    inner
}

fn parse_stmts_until_close(p: &mut Parser, segs: &mut Vec<Seg>) {
    // Parse statements until we hit ) or end
    let mut depth = 1i32;
    loop {
        skip_ws(p, segs);
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b')' { break; } // will be consumed by caller

        let start = p.pos;
        // Parse one statement
        parse_statement(p, segs, &[")"]);
        collect_seps(p, segs);

        if p.pos == start {
            let c = p.advance().unwrap_or(b')');
            if c == b')' { p.pos -= 1; break; }
            push_verb(segs, &[c]);
        }
    }
}

fn parse_backtick_inner(p: &mut Parser) -> Vec<Seg> {
    assert_eq!(p.peek(), Some(b'`'));
    p.pos += 1; // skip opening `
    let mut inner = Vec::new();
    loop {
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b'`' { p.pos += 1; break; }
        let start = p.pos;
        parse_statement(p, &mut inner, &[]);
        if p.pos == start {
            // No progress - check for ` terminator
            if p.peek() == Some(b'`') { p.pos += 1; break; }
            let c = p.advance().unwrap_or(b'`');
            push_verb(&mut inner, &[c]);
        }
        // collect separators
        collect_seps(p, &mut inner);
    }
    inner
}

fn parse_dq(p: &mut Parser) -> Seg {
    assert_eq!(p.peek(), Some(b'"'));
    p.pos += 1; // skip "

    let mut parts: Vec<DQSeg> = Vec::new();
    let mut lit = String::new();

    loop {
        if p.pos >= p.len() {
            // Unclosed string
            if !lit.is_empty() { parts.push(DQSeg::Lit(lit)); }
            break;
        }
        let c = p.input[p.pos];
        match c {
            b'"' => { p.pos += 1; break; }
            b'\\' => {
                // Escape sequence inside double quotes
                let nc = p.peek_at(1).unwrap_or(0);
                if nc == b'"' || nc == b'\\' || nc == b'$' || nc == b'`' || nc == b'\n' {
                    lit.push(c as char);
                    lit.push(nc as char);
                    p.pos += 2;
                } else {
                    lit.push(c as char);
                    p.pos += 1;
                }
            }
            b'$' => {
                if !lit.is_empty() { parts.push(DQSeg::Lit(lit.clone())); lit.clear(); }
                let c2 = p.peek_at(1).unwrap_or(0);
                match c2 {
                    b'(' => {
                        if p.peek_at(2) == Some(b'(') {
                            // $((...))
                            let arith = parse_arith_expansion_dollar(p);
                            parts.push(DQSeg::Arith(arith));
                        } else {
                            // $(...)
                            p.pos += 2;
                            let inner = parse_cmd_sub_inner(p);
                            if p.peek() == Some(b')') { p.pos += 1; }
                            parts.push(DQSeg::CmdSub("$(".to_string(), inner, ")".to_string()));
                        }
                    }
                    b'{' => {
                        let seg = parse_dq_dollar_brace(p);
                        parts.push(seg);
                    }
                    b'@' => { p.pos += 2; parts.push(DQSeg::Var("$@".to_string(), false)); }
                    b'*' => { p.pos += 2; parts.push(DQSeg::Var("$*".to_string(), false)); }
                    b'?' | b'$' | b'!' | b'#' => {
                        p.pos += 2;
                        parts.push(DQSeg::Var(format!("${}", c2 as char), false));
                    }
                    _ if c2.is_ascii_digit() => {
                        p.pos += 2;
                        // Check for multi-digit pitfall
                        if let Some(c3) = p.peek() {
                            if c3.is_ascii_digit() {
                                // Pitfall in double-quoted context - same handling
                                parts.push(DQSeg::Var(format!("${}", c2 as char), false));
                                // Don't consume the next digit
                                continue;
                            }
                        }
                        parts.push(DQSeg::Var(format!("${}", c2 as char), false));
                    }
                    _ if is_start(c2) => {
                        p.pos += 1; // skip $
                        let start = p.pos;
                        while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
                        let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                        let orig = format!("${}", name);
                        // Check if followed by identifier char
                        let next = p.peek().unwrap_or(0);
                        parts.push(DQSeg::Var(orig, false));
                    }
                    _ => { lit.push('$'); p.pos += 1; }
                }
            }
            b'`' => {
                if !lit.is_empty() { parts.push(DQSeg::Lit(lit.clone())); lit.clear(); }
                let inner = parse_backtick_inner(p);
                parts.push(DQSeg::CmdSub("`".to_string(), inner, "".to_string()));
            }
            _ => { lit.push(c as char); p.pos += 1; }
        }
    }

    if !lit.is_empty() { parts.push(DQSeg::Lit(lit)); }
    Seg::DQ(parts)
}

fn parse_dq_dollar_brace(p: &mut Parser) -> DQSeg {
    // ${...} inside double quotes
    let start = p.pos;
    p.pos += 2; // skip ${

    // Read variable name
    let name_start = p.pos;

    // Handle special chars
    let peek = p.peek().unwrap_or(0);
    if matches!(peek, b'#' | b'!' | b'@' | b'*' | b'?' | b'$') {
        // Could be ${#varname}, ${!var}, etc.
    }

    // Handle digits (positional params)
    if peek.is_ascii_digit() {
        while p.pos < p.len() && p.input[p.pos].is_ascii_digit() { p.pos += 1; }
        // Read rest until }
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return DQSeg::Var(orig, false);
    }

    // Skip optional # ! @ * ? $
    if matches!(peek, b'#' | b'!') { p.pos += 1; }

    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[name_start..p.pos]).to_string();

    let suffix_start = p.pos;
    let mut depth = 1i32;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'{' { depth += 1; p.pos += 1; }
        else if c == b'}' {
            depth -= 1;
            if depth == 0 { p.pos += 1; break; }
            p.pos += 1;
        } else if c == b'"' {
            // nested " inside ${...} - complex, just skip
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'"' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else {
            p.pos += 1;
        }
    }
    let suffix = String::from_utf8_lossy(&p.input[suffix_start..p.pos-1]).to_string();
    let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    // Determine if braces can be removed
    // Braces can be removed if: suffix is empty AND nothing follows that's an ident char
    // We check "nothing follows" by looking at what comes after in the DQ string
    // (we'll determine this contextually - for now, check if name is simple identifier)
    let can_remove = suffix.is_empty() 
        && !name.is_empty()
        && is_start(name.as_bytes()[0])
        && name.bytes().all(|c| ic(c));

    // Actually we need to check what comes next in the DQ string too
    // If next char is an ident char, we can't remove braces
    let next_in_dq = p.peek().unwrap_or(0);
    let can_remove_final = can_remove && (next_in_dq == b'"' || !ic(next_in_dq));
    // Wait - "can_remove" should only apply when the var is ALONE in the string
    // e.g. "${var}" (the whole string is just this var) - but we check later
    // For now, track the possibility

    DQSeg::Var(orig, can_remove_final)
}

fn parse_sq(p: &mut Parser) -> Seg {
    assert!(p.peek() == Some(b'\'') || (p.peek() == Some(b'$') && p.peek_at(1) == Some(b'\'')));
    let start = p.pos;
    let dollar = p.peek() == Some(b'$');
    if dollar { p.pos += 1; }
    p.pos += 1; // skip '
    while p.pos < p.len() && p.input[p.pos] != b'\'' {
        if p.input[p.pos] == b'\\' { p.pos += 1; } // skip escaped char
        p.pos += 1;
    }
    if p.pos < p.len() { p.pos += 1; } // skip closing '
    let s = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
    Seg::SQ(s)
}

