fn parse_assign_rhs(p: &mut Parser, segs: &mut Vec<Seg>) {
    // Parse the RHS of an assignment - $var is OK unquoted here (assignment context)
    if p.pos >= p.len() { return; }

    // Check for array assignment: (...)
    if p.peek() == Some(b'(') {
        push_verb(segs, b"("); p.pos += 1;
        loop {
            skip_inline_ws(p, segs);
            if p.pos >= p.len() { break; }
            if p.peek() == Some(b')') { push_verb(segs, b")"); p.pos += 1; break; }
            if p.peek() == Some(b'\n') { push_verb(segs, b"\n"); p.pos += 1; continue; }
            // Each element needs quoting
            parse_arg_word(p, segs, false);
        }
        return;
    }

    // Regular assignment - parse until whitespace
    // In assignment context, $var doesn't need quoting
    // But we still need to handle the various forms
    parse_assign_rhs_word(p, segs);
}

fn parse_assign_rhs_word(p: &mut Parser, segs: &mut Vec<Seg>) {
    // Parse assignment RHS - $var is safe here (no word splitting)
    // But if inside $(), those need quoting
    if p.pos >= p.len() { return; }

    let start = p.pos;
    loop {
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == b';' || c == b'&' || c == b'|' { break; }

        match c {
            b'"' => {
                let before = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                push_verb_str(segs, &before);
                let dq = parse_dq(p);
                segs.push(dq);
                return;
            }
            b'\'' => {
                let before = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                push_verb_str(segs, &before);
                let sq = parse_sq(p);
                segs.push(sq);
                return;
            }
            b'$' => {
                // In assignment context, $var is fine as-is
                // But $(cmd) might need quoting inside
                if p.peek_at(1) == Some(b'(') {
                    let before = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                    push_verb_str(segs, &before);
                    // $(...) in assignment context - parse contents but no outer quoting needed
                    if p.peek_at(2) == Some(b'(') {
                        // $((...)) arithmetic
                        let arith = parse_arith_expansion_dollar(p);
                        segs.push(Seg::Arith(arith));
                    } else {
                        p.pos += 2;
                        let inner = parse_cmd_sub_inner(p);
                        let close = if p.peek() == Some(b')') { p.pos += 1; ")" } else { "" };
                        segs.push(Seg::AlreadyQuoted("$(".to_string(), inner, close.to_string()));
                    }
                    return; // simplification: stop after first complex token
                }
                p.pos += 1;
            }
            b'`' => {
                let before = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                push_verb_str(segs, &before);
                let inner = parse_backtick_inner(p);
                segs.push(Seg::AlreadyQuoted("`".to_string(), inner, "`".to_string()));
                return;
            }
            _ => { p.pos += 1; }
        }
    }

    let text = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
    push_verb_str(segs, &text);
}

fn parse_arg_word(p: &mut Parser, segs: &mut Vec<Seg>, in_test: bool) {
    // Parse a word in command argument position
    // Unquoted $var needs quoting

    if p.pos >= p.len() { return; }

    // Collect a "word" which may be multiple adjacent quoted/unquoted parts
    let mut word_segs: Vec<Seg> = Vec::new();

    loop {
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];

        // Word terminators
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { break; }
        if c == b';' || c == b'&' || c == b'|' { break; }
        if c == b')' && !in_test { break; } // end of subshell
        if c == b']' && in_test { break; }

        match c {
            b'"' => {
                let dq = parse_dq(p);
                word_segs.push(dq);
            }
            b'\'' => {
                let sq = parse_sq(p);
                word_segs.push(sq);
            }
            b'$' => {
                let seg = parse_dollar_expr(p, in_test);
                word_segs.push(seg);
            }
            b'`' => {
                // Backtick - needs quoting
                let inner = parse_backtick_inner(p);
                // Check if there are any unquoted vars inside
                let needs_q = has_unsafe_vars(&inner);
                if needs_q {
                    word_segs.push(Seg::NeedQuote("$(`".to_string(), inner, "`".to_string()));
                } else {
                    word_segs.push(Seg::NeedQuote("$(`".to_string(), inner, "`".to_string()));
                }
            }
            b'<' | b'>' => {
                // Redirect
                break;
            }
            b'\\' => {
                // Escaped char
                if p.peek_at(1) == Some(b'\n') {
                    // Line continuation - part of next line
                    push_verb(segs, &p.input[p.pos..p.pos+2]);
                    p.pos += 2;
                    skip_inline_ws(p, segs);
                    continue;
                }
                let start = p.pos;
                p.pos += 2; // skip backslash and next char
                let text = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                if let Some(Seg::Verbatim(ref mut prev)) = word_segs.last_mut() {
                    prev.push_str(&text);
                } else {
                    word_segs.push(Seg::Verbatim(text));
                }
            }
            _ => {
                let start = p.pos;
                while p.pos < p.len() {
                    let c = p.input[p.pos];
                    if c == b'"' || c == b'\'' || c == b'$' || c == b'`' || c == b'\\' { break; }
                    if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { break; }
                    if c == b';' || c == b'|' || c == b'&' { break; }
                    if c == b')' && !in_test { break; }
                    if c == b']' && in_test { break; }
                    if c == b'<' || c == b'>' { break; }
                    p.pos += 1;
                }
                let text = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                if let Some(Seg::Verbatim(ref mut prev)) = word_segs.last_mut() {
                    prev.push_str(&text);
                } else {
                    word_segs.push(Seg::Verbatim(text));
                }
            }
        }
    }

    // Merge adjacent word segments
    merge_word_segs(word_segs, segs);
}

fn has_unsafe_vars(segs: &[Seg]) -> bool {
    for s in segs {
        match s {
            Seg::UVar(_, _) => return true,
            Seg::NeedQuote(_, inner, _) => if has_unsafe_vars(inner) { return true; }
            _ => {}
        }
    }
    false
}

fn merge_word_segs(mut word_segs: Vec<Seg>, segs: &mut Vec<Seg>) {
    // Handle concatenation of adjacent unquoted segments
    // The key rules:
    // 1. If there are any UnsafeVar segments, we need to wrap them in quotes
    // 2. Adjacent text+UnsafeVar or UnsafeVar+text may need to be merged into one DQ string

    if word_segs.is_empty() { return; }

    // Check if there are any unsafe vars or NeedQuote items
    let has_unsafe = word_segs.iter().any(|s| matches!(s, Seg::UVar(_, _) | Seg::NeedQuote(_, _, _)));

    if !has_unsafe {
        // No unsafe vars - just output everything as-is
        segs.extend(word_segs);
        return;
    }

    // We need to merge and quote things
    // Strategy: collect runs of unsafe/text into double-quoted strings

    // Simple case: single UnsafeVar
    if word_segs.len() == 1 {
        segs.extend(word_segs);
        return;
    }

    // Multiple segments - need careful merging
    // Group consecutive text+var into DQ strings
    let mut merged = merge_to_dq_if_needed(word_segs);
    segs.extend(merged);
}

fn merge_to_dq_if_needed(word_segs: Vec<Seg>) -> Vec<Seg> {
    // This is the complex merging logic
    // For now, just return as-is and let individual seg rendering handle it
    word_segs
}

fn parse_dollar_expr(p: &mut Parser, in_test: bool) -> Seg {
    assert_eq!(p.peek(), Some(b'$'));

    // Check what follows $
    let c2 = p.peek_at(1).unwrap_or(0);

    match c2 {
        b'(' => {
            if p.peek_at(2) == Some(b'(') {
                // $((...)) arithmetic
                let s = parse_arith_expansion_dollar(p);
                Seg::Arith(s)
            } else {
                // $(...) command substitution
                p.pos += 2; // skip $(
                let inner = parse_cmd_sub_inner(p);
                if p.peek() == Some(b')') { p.pos += 1; }
                // This needs quoting when in command position
                Seg::NeedQuote("$(".to_string(), inner, ")".to_string())
            }
        }
        b'{' => {
            // ${...}
            parse_dollar_brace(p, in_test)
        }
        b'@' => {
            p.pos += 2;
            Seg::UVar("$@".to_string(), "\"$@\"".to_string())
        }
        b'*' => {
            p.pos += 2;
            Seg::UVar("$*".to_string(), "\"$@\"".to_string())
        }
        b'?' | b'$' | b'!' | b'#' => {
            p.pos += 2;
            Seg::SafeVar(format!("${}", c2 as char))
        }
        b'\'' => {
            // $'...' ANSI C string
            p.pos += 1; // skip $
            let sq = parse_sq(p);
            sq
        }
        _ if c2.is_ascii_digit() => {
            // Positional parameter or multi-digit
            p.pos += 2;
            let name = format!("${}", c2 as char);
            // Check for multi-digit pitfall
            if let Some(c3) = p.peek() {
                if c3.is_ascii_digit() {
                    // This is a pitfall: $12 etc.
                    // Emit what we have, report error
                    let fname = p.filename.as_deref().unwrap_or("stdin");
                    // Find the line
                    let line = find_line_at(p, p.pos - 2);
                    let col = line.1;
                    eprintln!("{}: Unsupported syntax: Syntactic pitfall", fname);
                    eprintln!("{}", line.0);
                    eprintln!("{}^^^", " ".repeat(col));
                    eprintln!("This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.");
                    eprintln!("");
                    eprintln!("Try this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j");
                    eprintln!("");
                    eprintln!("Here is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".");
                    eprintln!("");
                    eprintln!("Syntactic pitfalls are deemed too dangerous to fix automatically");
                    eprintln!("(the purpose of Shellharden is to fix vulnerable code \u{2013} code that mostly does what it looks like, as opposed to code that never does what it looks like):");
                    eprintln!("* Fixing what it does would be 100% subtle and might slip through code review unnoticed.");
                    eprintln!("* Fixing its look would make a likely bug look intentional.");
                    p.had_error = true;
                    return Seg::Verbatim(name);
                }
            }
            Seg::UVar(name.clone(), format!("\"{}\"", name))
        }
        _ if is_start(c2) => {
            // Regular $identifier
            p.pos += 1; // skip $
            let start = p.pos;
            while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
            let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
            let orig = format!("${}", name);
            let trans = format!("\"${}\"", name);
            Seg::UVar(orig, trans)
        }
        _ => {
            // Just a $ sign
            p.pos += 1;
            Seg::Verbatim("$".to_string())
        }
    }
}

fn find_line_at(p: &Parser, pos: usize) -> (String, usize) {
    // Find the line containing 'pos' and the column
    let mut line_start = 0;
    for (i, &c) in p.input[..pos].iter().enumerate() {
        if c == b'\n' { line_start = i + 1; }
    }
    let line_end = p.input[line_start..].iter().position(|&c| c == b'\n')
        .map(|i| line_start + i)
        .unwrap_or(p.input.len());
    let line = String::from_utf8_lossy(&p.input[line_start..line_end]).to_string();
    let col = pos - line_start;
    (line, col)
}

fn parse_dollar_brace(p: &mut Parser, in_test: bool) -> Seg {
    let start = p.pos;
    p.pos += 2; // skip ${

    // Check what's inside
    let peek = p.peek().unwrap_or(0);

    // Handle special vars: ${#}, ${!}, ${@}, ${*}, ${?}, ${$}
    if peek == b'#' && (p.peek_at(1) == Some(b'}') || !is_start(p.peek_at(1).unwrap_or(0))) {
        // Length or $#
        // Read the rest
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    if matches!(peek, b'!' | b'@' | b'*' | b'?' | b'$') && p.peek_at(1) == Some(b'}') {
        p.pos += 2; // skip X}
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        if peek == b'@' || peek == b'*' {
            // ${@} -> "${@}", ${*} -> "${*}"
            let trans = format!("\"{}\"", orig);
            return Seg::UVar(orig, trans);
        }
        return Seg::SafeVar(orig);
    }

    // Handle ${!prefix*} and ${!prefix@} indirect
    if peek == b'!' {
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    // Handle ${#var} - length
    if peek == b'#' {
        let inner_start = p.pos;
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return Seg::SafeVar(orig);
    }

    // Regular variable: ${varname}, ${varname[@]}, ${varname:-default}, etc.
    // Read variable name
    let name_start = p.pos;
    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[name_start..p.pos]).to_string();

    // Read the rest until }
    let suffix_start = p.pos;
    let mut depth = 1i32;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'{' { depth += 1; p.pos += 1; }
        else if c == b'}' {
            depth -= 1;
            if depth == 0 { p.pos += 1; break; }
            p.pos += 1;
        } else if c == b'\'' {
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'\'' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else {
            p.pos += 1;
        }
    }
    let suffix = String::from_utf8_lossy(&p.input[suffix_start..p.pos-1]).to_string();
    let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    // Determine if this needs quoting and what the transform is
    // ${var} alone -> needs quoting, becomes "$var" (braces removed) in transform
    // ${var[@]}, ${var[*]}, ${var:-...}, etc -> needs quoting, keeps as-is
    // ${#var} -> safe (length)
    // ${!var} -> safe (indirect name expansion)

    if name.is_empty() {
        // Positional or special
        return Seg::SafeVar(orig);
    }

    // Check suffix to determine transformation
    let trans = if suffix.is_empty() {
        // "${varname}" - simple var with braces
        // In command position, needs quoting. Braces unnecessary.
        format!("\"{}\"", orig) // will be rendered as "$varname" when braces removed
    } else if suffix == "[@]" || suffix == "[*]" {
        // ${var[@]} or ${var[*]}
        if suffix == "[*]" {
            // ${var[*]} -> "${var[@]}"
            format!("\"${{{name}[@]}}\"")
        } else {
            format!("\"{}\"", orig)
        }
    } else {
        // Complex expansion: ${var:-default}, ${var/pat/rep}, etc.
        format!("\"{}\"", orig)
    };

    Seg::UVar(orig, trans)
}

fn parse_arith_expansion(p: &mut Parser) -> String {
    // Parse ((...)) or $((...))
    let start = p.pos;
    assert!(p.starts_with(b"(("));
    p.pos += 2;
    let mut depth = 1u32;
    while p.pos < p.len() {
        if p.starts_with(b"((") { depth += 1; p.pos += 2; }
        else if p.starts_with(b"))") {
            depth -= 1; p.pos += 2;
            if depth == 0 { break; }
        } else {
            p.pos += 1;
        }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_arith_expansion_dollar(p: &mut Parser) -> String {
    // Parse $((...)): starts at $
    assert!(p.starts_with(b"$(("));
    let start = p.pos;
    p.pos += 3; // skip $((
    let mut depth = 1u32;
    while p.pos < p.len() {
        if p.starts_with(b"((") { depth += 1; p.pos += 2; }
        else if p.starts_with(b"))") {
            depth -= 1; p.pos += 2;
            if depth == 0 { break; }
        } else {
            p.pos += 1;
        }
    }
    String::from_utf8_lossy(&p.input[start..p.pos]).to_string()
}

fn parse_cmd_sub_inner(p: &mut Parser) -> Vec<Seg> {
    // Parse the inside of $(...)
    let mut inner = Vec::new();
    parse_stmts_until_close(p, &mut inner);
    inner
}

fn parse_stmts_until_close(p: &mut Parser, segs: &mut Vec<Seg>) {
    // Parse statements until we hit ) or end
    let mut depth = 1i32;
    loop {
        skip_ws(p, segs);
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b')' { break; } // will be consumed by caller

        let start = p.pos;
        // Parse one statement
        parse_statement(p, segs, &[")"]);
        collect_seps(p, segs);

        if p.pos == start {
            let c = p.advance().unwrap_or(b')');
            if c == b')' { p.pos -= 1; break; }
            push_verb(segs, &[c]);
        }
    }
}

fn parse_backtick_inner(p: &mut Parser) -> Vec<Seg> {
    assert_eq!(p.peek(), Some(b'`'));
    p.pos += 1; // skip opening `
    let mut inner = Vec::new();
    loop {
        if p.pos >= p.len() { break; }
        let c = p.input[p.pos];
        if c == b'`' { p.pos += 1; break; }
        let start = p.pos;
        parse_statement(p, &mut inner, &[]);
        if p.pos == start {
            // No progress - check for ` terminator
            if p.peek() == Some(b'`') { p.pos += 1; break; }
            let c = p.advance().unwrap_or(b'`');
            push_verb(&mut inner, &[c]);
        }
        // collect separators
        collect_seps(p, &mut inner);
    }
    inner
}

fn parse_dq(p: &mut Parser) -> Seg {
    assert_eq!(p.peek(), Some(b'"'));
    p.pos += 1; // skip "

    let mut parts: Vec<DQSeg> = Vec::new();
    let mut lit = String::new();

    loop {
        if p.pos >= p.len() {
            // Unclosed string
            if !lit.is_empty() { parts.push(DQSeg::Lit(lit)); }
            break;
        }
        let c = p.input[p.pos];
        match c {
            b'"' => { p.pos += 1; break; }
            b'\\' => {
                // Escape sequence inside double quotes
                let nc = p.peek_at(1).unwrap_or(0);
                if nc == b'"' || nc == b'\\' || nc == b'$' || nc == b'`' || nc == b'\n' {
                    lit.push(c as char);
                    lit.push(nc as char);
                    p.pos += 2;
                } else {
                    lit.push(c as char);
                    p.pos += 1;
                }
            }
            b'$' => {
                if !lit.is_empty() { parts.push(DQSeg::Lit(lit.clone())); lit.clear(); }
                let c2 = p.peek_at(1).unwrap_or(0);
                match c2 {
                    b'(' => {
                        if p.peek_at(2) == Some(b'(') {
                            // $((...))
                            let arith = parse_arith_expansion_dollar(p);
                            parts.push(DQSeg::Arith(arith));
                        } else {
                            // $(...)
                            p.pos += 2;
                            let inner = parse_cmd_sub_inner(p);
                            if p.peek() == Some(b')') { p.pos += 1; }
                            parts.push(DQSeg::CmdSub("$(".to_string(), inner, ")".to_string()));
                        }
                    }
                    b'{' => {
                        let seg = parse_dq_dollar_brace(p);
                        parts.push(seg);
                    }
                    b'@' => { p.pos += 2; parts.push(DQSeg::Var("$@".to_string(), false)); }
                    b'*' => { p.pos += 2; parts.push(DQSeg::Var("$*".to_string(), false)); }
                    b'?' | b'$' | b'!' | b'#' => {
                        p.pos += 2;
                        parts.push(DQSeg::Var(format!("${}", c2 as char), false));
                    }
                    _ if c2.is_ascii_digit() => {
                        p.pos += 2;
                        // Check for multi-digit pitfall
                        if let Some(c3) = p.peek() {
                            if c3.is_ascii_digit() {
                                // Pitfall in double-quoted context - same handling
                                parts.push(DQSeg::Var(format!("${}", c2 as char), false));
                                // Don't consume the next digit
                                continue;
                            }
                        }
                        parts.push(DQSeg::Var(format!("${}", c2 as char), false));
                    }
                    _ if is_start(c2) => {
                        p.pos += 1; // skip $
                        let start = p.pos;
                        while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
                        let name = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
                        let orig = format!("${}", name);
                        // Check if followed by identifier char
                        let next = p.peek().unwrap_or(0);
                        parts.push(DQSeg::Var(orig, false));
                    }
                    _ => { lit.push('$'); p.pos += 1; }
                }
            }
            b'`' => {
                if !lit.is_empty() { parts.push(DQSeg::Lit(lit.clone())); lit.clear(); }
                let inner = parse_backtick_inner(p);
                parts.push(DQSeg::CmdSub("`".to_string(), inner, "".to_string()));
            }
            _ => { lit.push(c as char); p.pos += 1; }
        }
    }

    if !lit.is_empty() { parts.push(DQSeg::Lit(lit)); }
    Seg::DQ(parts)
}

fn parse_dq_dollar_brace(p: &mut Parser) -> DQSeg {
    // ${...} inside double quotes
    let start = p.pos;
    p.pos += 2; // skip ${

    // Read variable name
    let name_start = p.pos;

    // Handle special chars
    let peek = p.peek().unwrap_or(0);
    if matches!(peek, b'#' | b'!' | b'@' | b'*' | b'?' | b'$') {
        // Could be ${#varname}, ${!var}, etc.
    }

    // Handle digits (positional params)
    if peek.is_ascii_digit() {
        while p.pos < p.len() && p.input[p.pos].is_ascii_digit() { p.pos += 1; }
        // Read rest until }
        let mut depth = 1i32;
        while p.pos < p.len() {
            if p.input[p.pos] == b'{' { depth += 1; }
            else if p.input[p.pos] == b'}' {
                depth -= 1;
                if depth == 0 { p.pos += 1; break; }
            }
            p.pos += 1;
        }
        let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
        return DQSeg::Var(orig, false);
    }

    // Skip optional # ! @ * ? $
    if matches!(peek, b'#' | b'!') { p.pos += 1; }

    while p.pos < p.len() && ic(p.input[p.pos]) { p.pos += 1; }
    let name = String::from_utf8_lossy(&p.input[name_start..p.pos]).to_string();

    let suffix_start = p.pos;
    let mut depth = 1i32;
    while p.pos < p.len() {
        let c = p.input[p.pos];
        if c == b'{' { depth += 1; p.pos += 1; }
        else if c == b'}' {
            depth -= 1;
            if depth == 0 { p.pos += 1; break; }
            p.pos += 1;
        } else if c == b'"' {
            // nested " inside ${...} - complex, just skip
            p.pos += 1;
            while p.pos < p.len() && p.input[p.pos] != b'"' { p.pos += 1; }
            if p.pos < p.len() { p.pos += 1; }
        } else {
            p.pos += 1;
        }
    }
    let suffix = String::from_utf8_lossy(&p.input[suffix_start..p.pos-1]).to_string();
    let orig = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();

    // Determine if braces can be removed
    // Braces can be removed if: suffix is empty AND nothing follows that's an ident char
    // We check "nothing follows" by looking at what comes after in the DQ string
    // (we'll determine this contextually - for now, check if name is simple identifier)
    let can_remove = suffix.is_empty() 
        && !name.is_empty()
        && is_start(name.as_bytes()[0])
        && name.bytes().all(|c| ic(c));

    // Actually we need to check what comes next in the DQ string too
    // If next char is an ident char, we can't remove braces
    let next_in_dq = p.peek().unwrap_or(0);
    let can_remove_final = can_remove && (next_in_dq == b'"' || !ic(next_in_dq));
    // Wait - "can_remove" should only apply when the var is ALONE in the string
    // e.g. "${var}" (the whole string is just this var) - but we check later
    // For now, track the possibility

    DQSeg::Var(orig, can_remove_final)
}

fn parse_sq(p: &mut Parser) -> Seg {
    assert!(p.peek() == Some(b'\'') || (p.peek() == Some(b'$') && p.peek_at(1) == Some(b'\'')));
    let start = p.pos;
    let dollar = p.peek() == Some(b'$');
    if dollar { p.pos += 1; }
    p.pos += 1; // skip '
    while p.pos < p.len() && p.input[p.pos] != b'\'' {
        if p.input[p.pos] == b'\\' { p.pos += 1; } // skip escaped char
        p.pos += 1;
    }
    if p.pos < p.len() { p.pos += 1; } // skip closing '
    let s = String::from_utf8_lossy(&p.input[start..p.pos]).to_string();
    Seg::SQ(s)
}

