    DQArith,     // $((...)) inside double quotes
    SQ,          // Single-quoted string
    Arith,       // $((...)) arithmetic outside quotes
    Heredoc,     // Heredoc content (from << to closing delimiter)
    NQOpen,      // Opening " being added (suggestion)  
    NQClose,     // Closing " being added (suggestion)
    CmdSubOpen,  // $( or `
