    NQClose,     // Closing " being added (suggestion)
    CmdSubOpen,  // $( or `
    CmdSubClose, // ) or `
    ProcSubOpen, // <( or >(
    ProcSubClose,// )
}

#[derive(Debug, Clone)]
struct Token {
    kind: TKind,
    text: String,      // Original text
    transform: String, // Transformed text (if different)
}

impl Token {
    fn new(kind: TKind, text: &str) -> Self {
        Token { kind, text: text.to_string(), transform: text.to_string() }
    }
    fn trans(kind: TKind, orig: &str, trans: &str) -> Self {
        Token { kind, text: orig.to_string(), transform: trans.to_string() }
    }
}

struct Tokenizer<'a> {
    input: &'a [u8],
    pos: usize,
    fname: Option<&'a str>,
    pub had_error: bool,
    tokens: Vec<Token>,
}

impl<'a> Tokenizer<'a> {
    fn new(input: &'a [u8], fname: Option<&'a str>) -> Self {
        Tokenizer { input, pos: 0, fname, had_error: false, tokens: Vec::new() }
    }
    fn peek(&self) -> Option<u8> { self.input.get(self.pos).copied() }
    fn peek_at(&self, off: usize) -> Option<u8> { self.input.get(self.pos + off).copied() }
    fn advance(&mut self) -> Option<u8> {
        let c = self.input.get(self.pos).copied();
        if c.is_some() { self.pos += 1; }
        c
    }
    fn sw(&self, s: &[u8]) -> bool { self.input[self.pos..].starts_with(s) }
    fn rest(&self) -> &[u8] { &self.input[self.pos..] }
    fn emit(&mut self, kind: TKind, text: &str) {
        self.tokens.push(Token::new(kind, text));
    }
    fn emit_trans(&mut self, kind: TKind, orig: &str, trans: &str) {
        self.tokens.push(Token::trans(kind, orig, trans));
    }
    fn collect_str(&self, start: usize) -> &str {
        std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("")
    }
    fn read_ident(&mut self) -> String {
        let start = self.pos;
        while self.pos < self.input.len() && is_ic(self.input[self.pos]) { self.pos += 1; }
        self.collect_str(start).to_string()
    }
}

fn is_ic(c: u8) -> bool { c.is_ascii_alphanumeric() || c == b'_' }
fn is_is(c: u8) -> bool { c.is_ascii_alphabetic() || c == b'_' }

fn parse_content(content: &str, fname: Option<&str>) -> Result<Vec<Token>, ()> {
    let mut t = Tokenizer::new(content.as_bytes(), fname);
    parse_top(&mut t);
    if t.had_error { Err(()) }
    else { Ok(t.tokens) }
}

// Top-level parsing context
fn parse_top(t: &mut Tokenizer) {
    while t.pos < t.input.len() {
        parse_newline_list(t);
        if t.pos >= t.input.len() { break; }
        let start = t.pos;
        parse_compound_list(t, &[]);
        if t.pos == start {
            let c = t.advance().unwrap_or(b'\n');
            t.emit(TKind::Verbatim, &(c as char).to_string());
        }
    }
}

fn parse_newline_list(t: &mut Tokenizer) {
    let start = t.pos;
    while t.pos < t.input.len() {
        let c = t.input[t.pos];
        if c == b'\n' || c == b'\r' || c == b' ' || c == b'\t' {
            t.pos += 1;
        } else if c == b'\\' && t.peek_at(1) == Some(b'\n') {
            t.pos += 2;
        } else {
            break;
        }
    }
    if t.pos > start {
        let s = std::str::from_utf8(&t.input[start..t.pos]).unwrap_or("");
        t.emit(TKind::Verbatim, s);
    }
}

fn skip_blanks(t: &mut Tokenizer) {
    let start = t.pos;
    while t.pos < t.input.len() {
        let c = t.input[t.pos];
        if c == b' ' || c == b'\t' { t.pos += 1; }
        else { break; }
    }
    if t.pos > start {
        let s = std::str::from_utf8(&t.input[start..t.pos]).unwrap_or("");
        t.emit(TKind::Verbatim, s);
    }
}

// Parse a list of commands until a stop token
fn parse_compound_list(t: &mut Tokenizer, stops: &[&[u8]]) {
    loop {
        parse_newline_list(t);
        if t.pos >= t.input.len() { break; }
        if at_any_stop(t, stops) { break; }
        let start = t.pos;
        parse_and_or(t, stops);
        if t.pos == start { break; }
        // Separator
        parse_separator(t);
    }
}

fn at_any_stop(t: &Tokenizer, stops: &[&[u8]]) -> bool {
    for stop in stops {
        if t.input[t.pos..].starts_with(stop) {
            let after = t.peek_at(stop.len()).unwrap_or(0);
            if !is_ic(after) { return true; }
        }
    }
    false
}

fn parse_separator(t: &mut Tokenizer) {
    let start = t.pos;
    // & || && | ;
    if t.sw(b"||") || t.sw(b"&&") || t.sw(b"|&") {
        t.emit(TKind::Verbatim, std::str::from_utf8(&t.input[t.pos..t.pos+2]).unwrap_or(""));
        t.pos += 2;
        parse_newline_list(t);
    } else if t.peek() == Some(b'|') {
        t.emit(TKind::Verbatim, "|");
        t.pos += 1;
        parse_newline_list(t);
    } else if t.peek() == Some(b'&') {
        t.emit(TKind::Verbatim, "&");
        t.pos += 1;
        parse_newline_list(t);
    } else if t.peek() == Some(b';') {
        t.emit(TKind::Verbatim, ";");
        t.pos += 1;
        parse_newline_list(t);
    }
}

fn parse_and_or(t: &mut Tokenizer, stops: &[&[u8]]) {
    parse_pipeline(t, stops);
}

fn parse_pipeline(t: &mut Tokenizer, stops: &[&[u8]]) {
    // Optional '!'
    if t.sw(b"! ") || (t.peek() == Some(b'!') && t.peek_at(1).map(|c| !is_ic(c)).unwrap_or(true)) {
        t.emit(TKind::Keyword, "!");
        t.pos += 1;
        skip_blanks(t);
    }
    parse_command(t, stops);
}

// Peek to see what kind of command follows
fn parse_command(t: &mut Tokenizer, stops: &[&[u8]]) {
    skip_blanks(t);
    if t.pos >= t.input.len() { return; }
    if t.peek() == Some(b'#') {
        parse_comment(t);
        return;
    }
    // Check for compound commands
    let kw = peek_kw(t);
    match kw {
        b"if" => { parse_if(t); return; }
        b"while" | b"until" => { parse_while_until(t); return; }
        b"for" => { parse_for(t); return; }
        b"select" => { parse_select(t); return; }
        b"case" => { parse_case(t); return; }
        b"function" => { parse_function_kw(t); return; }
        b"{" => { parse_brace_group(t); return; }
        b"(" => { parse_subshell(t); return; }
        _ => {}
    }
    // Check for function definition
    if looks_func_def(t) {
        parse_func_def(t);
        return;
    }
    // Simple command
    parse_simple_command(t, stops);
}

fn peek_kw<'a>(t: &'a Tokenizer) -> &'a [u8] {
    let start = t.pos;
    let mut i = start;
    while i < t.input.len() && is_ic(t.input[i]) { i += 1; }
    if i == start {
        // Single char keywords
        match t.input.get(start).copied() {
            Some(b'{') => return b"{",
            Some(b'(') => return b"(",
            _ => {}
        }
        return b"";
    }
    &t.input[start..i]
}

fn looks_func_def(t: &Tokenizer) -> bool {
    let mut i = t.pos;
    if i >= t.input.len() || !is_is(t.input[i]) { return false; }
    while i < t.input.len() && is_ic(t.input[i]) { i += 1; }
    while i < t.input.len() && t.input[i] == b' ' { i += 1; }
    if i >= t.input.len() || t.input[i] != b'(' { return false; }
    i += 1;
    while i < t.input.len() && t.input[i] == b' ' { i += 1; }
    i < t.input.len() && t.input[i] == b')'
}

fn parse_comment(t: &mut Tokenizer) {
    let start = t.pos;
    while t.pos < t.input.len() && t.input[t.pos] != b'\n' { t.pos += 1; }
    let s = t.collect_str(start).to_string();
    t.emit(TKind::Comment, &s);
}

fn parse_if(t: &mut Tokenizer) {
    // "if" keyword (no trailing space - space comes from source)
    t.emit(TKind::Keyword, "if"); t.pos += 2;
    parse_newline_list(t);
    parse_compound_list(t, &[b"then"]);
    parse_newline_list(t);
    if try_kw(t, b"then") {
        loop {
            parse_newline_list(t);
            if at_kw(t, b"fi") {
                try_kw(t, b"fi"); break;
            } else if at_kw(t, b"elif") {
                t.emit(TKind::Keyword, "elif"); t.pos += 4;
                parse_newline_list(t);
                parse_compound_list(t, &[b"then"]);
                parse_newline_list(t);
                try_kw(t, b"then");
            } else if at_kw(t, b"else") {
                try_kw(t, b"else");
                parse_newline_list(t);
                parse_compound_list(t, &[b"fi"]);
                parse_newline_list(t);
                try_kw(t, b"fi");
                break;
            } else {
                parse_compound_list(t, &[b"fi", b"elif", b"else"]);
                parse_newline_list(t);
                if at_kw(t, b"fi") { try_kw(t, b"fi"); }
                break;
            }
        }
    }
}

fn at_kw(t: &Tokenizer, kw: &[u8]) -> bool {
    t.input[t.pos..].starts_with(kw) && !is_ic(t.peek_at(kw.len()).unwrap_or(0))
}

fn try_kw(t: &mut Tokenizer, kw: &[u8]) -> bool {
    if at_kw(t, kw) {
        let s = std::str::from_utf8(kw).unwrap_or("");
        t.emit(TKind::Keyword, s);
        t.pos += kw.len();
        return true;
    }
    false
}

fn parse_while_until(t: &mut Tokenizer) {
    let kw = t.read_ident();
    t.emit(TKind::Keyword, &kw);
    parse_newline_list(t);
    parse_compound_list(t, &[b"do"]);
    parse_newline_list(t);
    if try_kw(t, b"do") {
        parse_newline_list(t);
        parse_compound_list(t, &[b"done"]);
        parse_newline_list(t);
        try_kw(t, b"done");
    }
}

fn parse_for(t: &mut Tokenizer) {
    t.pos += 3; // skip "for"
    skip_blanks(t);

    // Check for C-style for((
    if t.sw(b"((") {
        t.emit(TKind::Keyword, "for");
        let arith = read_arith(t);
        t.emit(TKind::Arith, &arith);
        parse_newline_list(t);
        skip_sep_semi(t);
        parse_newline_list(t);
        if try_kw(t, b"do") {
            parse_newline_list(t);
            parse_compound_list(t, &[b"done"]);
            parse_newline_list(t);
            try_kw(t, b"done");
        }
        return;
    }

    // Regular for: "for VAR in ITEMS; do BODY done"
    // "for " is keyword with trailing space
    t.emit(TKind::Keyword, "for ");

    // Variable name (colored as assign-lhs)
    let var = t.read_ident();
    t.emit(TKind::AssignLhs, &var);

    skip_blanks(t);

    // Optional " in ITEMS"
    // The space before "in" is a keyword token
    // "in" itself is plain text (NOT bold!)
    // Items are plain/quoted
    if at_kw(t, b"in") {
        // Emit the space before "in" as keyword
        // Actually: looking at the expected output, the space between var and "in" is [bold]" "[reset]
        // and "in" is NOT bold, then items are plain
        t.emit(TKind::Keyword, " ");  // space before "in" as bold
        // Actually "in" in for loop is NOT colored as keyword! Let me re-check.
        // From earlier analysis: [bold]"for "[reset][ASSIGN]"f"[reset][bold]" "[reset] in files
        // So "in" and items are plain text! Not bold!
        // So we should NOT emit "in" as keyword.
        // Instead, collect from "in" to "; do" as verbatim, but transform $var items.
        parse_for_in_items(t);
    }

    parse_newline_list(t);
    skip_sep_semi(t);
    parse_newline_list(t);
    if try_kw(t, b"do") {
        parse_newline_list(t);
        parse_compound_list(t, &[b"done"]);
        parse_newline_list(t);
        try_kw(t, b"done");
    }
}

fn skip_sep_semi(t: &mut Tokenizer) {
    if t.peek() == Some(b';') {
        t.emit(TKind::Verbatim, ";");
        t.pos += 1;
    }
}

fn read_arith(t: &mut Tokenizer) -> String {
    // Read ((...))
    assert!(t.sw(b"(("));
    let start = t.pos;
    t.pos += 2;
    let mut depth = 1u32;
    while t.pos < t.input.len() {
        if t.sw(b"((") { depth += 1; t.pos += 2; }
        else if t.sw(b"))") { depth -= 1; t.pos += 2; if depth == 0 { break; } }
        else { t.pos += 1; }
    }
    t.collect_str(start).to_string()
}

fn parse_for_in_items(t: &mut Tokenizer) {
    // Parse "in ITEMS" where ITEMS are transformed for the for-loop context
    // "in" is plain text, items may be $var -> "${var[@]}"

    // Emit "in" as verbatim (not keyword!)
    if at_kw(t, b"in") {
        t.emit(TKind::Verbatim, "in");
        t.pos += 2;
    }

    // Parse items until ; or do or newline
    loop {
        skip_blanks(t);
        if t.pos >= t.input.len() { break; }
        let c = t.input[t.pos];
        if c == b';' || c == b'\n' || c == b'\r' { break; }
        if at_kw(t, b"do") { break; }
        parse_for_item(t);
    }
}

fn parse_for_item(t: &mut Tokenizer) {
    if t.pos >= t.input.len() { return; }
    let c = t.input[t.pos];
    match c {
        b'"' => parse_dq(t, false),
        b'\'' | b'$' if c == b'$' && t.peek_at(1) == Some(b'\'') => parse_sq(t),
        b'$' => parse_dollar_for(t),
        b'`' => parse_backtick(t, true), // needs quoting in for context
        _ => {
            // Plain word
            let start = t.pos;
            while t.pos < t.input.len() {
                let c = t.input[t.pos];
                if c == b' ' || c == b'\t' || c == b';' || c == b'\n' { break; }
                if c == b'"' || c == b'\'' || c == b'$' || c == b'`' { break; }
                if at_kw(t, b"do") { break; }
                t.pos += 1;
            }
            let s = t.collect_str(start).to_string();
            if !s.is_empty() { t.emit(TKind::Verbatim, &s); }
        }
    }
}

fn parse_dollar_for(t: &mut Tokenizer) {
    // In for-in context: $var -> "${var[@]}", $() -> needs quoting
    let c2 = t.peek_at(1).unwrap_or(0);
    match c2 {
        b'@' => { t.emit_trans(TKind::UVar, "$@", "\"$@\""); t.pos += 2; }
        b'*' => { t.emit_trans(TKind::UVar, "$*", "\"$@\""); t.pos += 2; }
        b'?' | b'$' | b'!' | b'#' => {
            t.emit_trans(TKind::UVar, &format!("${}", c2 as char), &format!("\"${}\"", c2 as char));
            t.pos += 2;
        }
        b'(' => {
            if t.peek_at(2) == Some(b'(') {
                // $((arith)) - safe but needs quoting in for context
                let s = read_dollar_arith(t);
                t.emit(TKind::NQOpen, "\"");
                t.emit(TKind::Arith, &s);
                t.emit(TKind::NQClose, "\"");
            } else {
                // $(...) needs quoting
                t.pos += 2; // skip $(
                t.emit(TKind::NQOpen, "\"");
                t.emit(TKind::CmdSubOpen, "$(");
                parse_cmd_sub_inner(t);
                if t.peek() == Some(b')') { t.emit(TKind::CmdSubClose, ")"); t.pos += 1; }
                t.emit(TKind::NQClose, "\"");
            }
        }
        b'{' => {
            // ${...} in for context
            let (orig, trans) = parse_dollar_brace_for(t);
            t.emit_trans(TKind::UVar, &orig, &trans);
        }
        _ if c2.is_ascii_digit() => {
            t.pos += 2;
            let orig = format!("${}", c2 as char);
            // Check for multi-digit pitfall
            if t.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                emit_pitfall_error(t, &orig, t.pos - 2);
                t.emit(TKind::Verbatim, &orig);
                return;
            }
            t.emit_trans(TKind::UVar, &orig, &format!("\"${}\"", c2 as char));
        }
        _ if is_is(c2) => {
            t.pos += 1; // skip $
            let name = t.read_ident();
            let orig = format!("${}", name);
            let trans = format!("\"${{{name}[@]}}\"");
            t.emit_trans(TKind::UVar, &orig, &trans);
        }
        _ => {
            t.emit(TKind::Verbatim, "$");
            t.pos += 1;
        }
    }
}

fn parse_dollar_brace_for(t: &mut Tokenizer) -> (String, String) {
    let start = t.pos;
    t.pos += 2; // skip ${

    // Read variable name
    let name_start = t.pos;
    let peek = t.peek().unwrap_or(0);
    if matches!(peek, b'#' | b'!') { t.pos += 1; }
    while t.pos < t.input.len() && is_ic(t.input[t.pos]) { t.pos += 1; }
    let name = std::str::from_utf8(&t.input[name_start..t.pos]).unwrap_or("").to_string();

    // Read rest
    let suf_start = t.pos;
    let mut depth = 1i32;
    while t.pos < t.input.len() {
        match t.input[t.pos] {
            b'{' => { depth += 1; t.pos += 1; }
            b'}' => { depth -= 1; t.pos += 1; if depth == 0 { break; } }
            b'\'' => { t.pos += 1; while t.pos < t.input.len() && t.input[t.pos] != b'\'' { t.pos += 1; } if t.pos < t.input.len() { t.pos += 1; } }
            _ => { t.pos += 1; }
        }
    }
    let suffix = std::str::from_utf8(&t.input[suf_start..t.pos.saturating_sub(1)]).unwrap_or("").to_string();
    let orig = t.collect_str(start).to_string();

    let trans = if suffix.is_empty() {
        format!("\"${{{name}[@]}}\"")
    } else if suffix == "[@]" {
        format!("\"${{{name}[@]}}\"")
    } else if suffix == "[*]" {
        format!("\"${{{name}[@]}}\"")
    } else {
        format!("\"{}\"", orig)
    };
    (orig, trans)
}

fn read_dollar_arith(t: &mut Tokenizer) -> String {
    assert!(t.sw(b"$(("));
    let start = t.pos;
    t.pos += 3;
    let mut depth = 1u32;
    while t.pos < t.input.len() {
        if t.sw(b"((") { depth += 1; t.pos += 2; }
        else if t.sw(b"))") { depth -= 1; t.pos += 2; if depth == 0 { break; } }
        else { t.pos += 1; }
    }
    t.collect_str(start).to_string()
}

fn parse_select(t: &mut Tokenizer) {
    t.pos += 6; // "select"
    t.emit(TKind::Keyword, "select ");
    skip_blanks(t);
    let var = t.read_ident();
    t.emit(TKind::AssignLhs, &var);
    skip_blanks(t);
    // " " before "in" is bold
    t.emit(TKind::Keyword, " ");
    // "in" is NOT bold in for/select
    if at_kw(t, b"in") {
        t.emit(TKind::Verbatim, "in");
        t.pos += 2;
    }
    // items are verbatim until ; or do
    let start = t.pos;
    loop {
        if t.pos >= t.input.len() { break; }
        let c = t.input[t.pos];
        if c == b';' || c == b'\n' { break; }
        if at_kw(t, b"do") { break; }
        // Parse items as regular args
        parse_arg(t, false, &[b';', b'\n'], &[b"do"]);
    }
    parse_newline_list(t);
    skip_sep_semi(t);
    parse_newline_list(t);
    if try_kw(t, b"do") {
        parse_newline_list(t);
        parse_compound_list(t, &[b"done"]);
        parse_newline_list(t);
        try_kw(t, b"done");
    }
}

fn parse_case(t: &mut Tokenizer) {
    t.pos += 4; // "case"
    // "case " keyword includes trailing space
    t.emit(TKind::Keyword, "case ");
    skip_blanks(t);
    // The case word is in magic context (unquoted OK)
    let case_word = read_case_word(t);
    t.emit(TKind::SafeVar, &case_word);
    skip_blanks(t);
    // " in" is a keyword including the leading space
    if at_kw(t, b"in") {
        t.emit(TKind::Keyword, " in");
        t.pos += 2;
    }
    parse_newline_list(t);
    // Parse case items
    loop {
        parse_newline_list(t);
        if t.pos >= t.input.len() { break; }
        if at_kw(t, b"esac") { try_kw(t, b"esac"); break; }
        // Optional (
        if t.peek() == Some(b'(') { t.emit(TKind::Verbatim, "("); t.pos += 1; }
        // Pattern - verbatim until )
        parse_case_pattern(t);
        if t.peek() == Some(b')') { t.emit(TKind::Verbatim, ")"); t.pos += 1; }
        parse_newline_list(t);
        // Body until ;;
        parse_compound_list(t, &[b";;", b";&", b";;&", b"esac"]);
        // Consume ;; etc.
        if t.sw(b";;") { t.emit(TKind::Verbatim, ";;"); t.pos += 2; }
        else if t.sw(b";&") { t.emit(TKind::Verbatim, ";&"); t.pos += 2; }
        else if t.sw(b";;&") { t.emit(TKind::Verbatim, ";;&"); t.pos += 3; }
    }
}

fn read_case_word(t: &mut Tokenizer) -> String {
    // Read the case expression verbatim (magic context)
    let start = t.pos;
    while t.pos < t.input.len() {
        let c = t.input[t.pos];
        if c == b'\n' { break; }
        if at_kw(t, b"in") { break; }
        match c {
            b'"' => { t.pos += 1; while t.pos < t.input.len() && t.input[t.pos] != b'"' { t.pos += 1; } if t.pos < t.input.len() { t.pos += 1; } }
            b'\'' => { t.pos += 1; while t.pos < t.input.len() && t.input[t.pos] != b'\'' { t.pos += 1; } if t.pos < t.input.len() { t.pos += 1; } }
            _ => { t.pos += 1; }
        }
    }
    // Trim trailing whitespace
    let end = t.pos;
    let s = std::str::from_utf8(&t.input[start..end]).unwrap_or("").trim_end().to_string();
    // Rewind to after the word (before whitespace)
    t.pos = start + s.len();
    s
}

fn parse_case_pattern(t: &mut Tokenizer) {
    // Pattern verbatim until )
    let start = t.pos;
    while t.pos < t.input.len() {
        let c = t.input[t.pos];
        if c == b')' || c == b'\n' { break; }
        t.pos += 1;
    }
    let s = t.collect_str(start).to_string();
    t.emit(TKind::Verbatim, &s);
}

fn parse_function_kw(t: &mut Tokenizer) {
    t.pos += 8; // "function"
    t.emit(TKind::Keyword, "function");
    skip_blanks(t);
    // Function name
    let start = t.pos;
    while t.pos < t.input.len() {
        let c = t.input[t.pos];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'(' || c == b'{' { break; }
        t.pos += 1;
    }
    let name = t.collect_str(start).to_string();
    t.emit(TKind::Cmd, &name);
    skip_blanks(t);
    // Optional ()
    if t.peek() == Some(b'(') {
        t.pos += 1;
        while t.pos < t.input.len() && t.input[t.pos] == b' ' { t.pos += 1; }
        if t.peek() == Some(b')') { t.pos += 1; }
        t.emit(TKind::Verbatim, "()");
    }
    parse_newline_list(t);
    parse_func_body(t);
}

fn parse_func_def(t: &mut Tokenizer) {
    let start = t.pos;
    while t.pos < t.input.len() && is_ic(t.input[t.pos]) { t.pos += 1; }
    let name = t.collect_str(start).to_string();
    t.emit(TKind::Cmd, &name);
    // ()
    while t.pos < t.input.len() && t.input[t.pos] == b' ' { t.pos += 1; }
    if t.peek() == Some(b'(') { t.pos += 1; }
    while t.pos < t.input.len() && t.input[t.pos] == b' ' { t.pos += 1; }
    if t.peek() == Some(b')') { t.pos += 1; }
    t.emit(TKind::Verbatim, "()");
    parse_newline_list(t);
    parse_func_body(t);
}

fn parse_func_body(t: &mut Tokenizer) {
    if t.peek() == Some(b'{') {
        parse_brace_group(t);
    } else if t.peek() == Some(b'(') {
        parse_subshell(t);
    }
}

fn parse_brace_group(t: &mut Tokenizer) {
    t.emit(TKind::Keyword, "{"); t.pos += 1;
    parse_newline_list(t);
    parse_compound_list(t, &[b"}"]);
    parse_newline_list(t);
    if t.peek() == Some(b'}') { t.emit(TKind::Keyword, "}"); t.pos += 1; }
}

fn parse_subshell(t: &mut Tokenizer) {
    t.emit(TKind::Verbatim, "("); t.pos += 1;
    parse_newline_list(t);
    parse_compound_list(t, &[b")"]);
    parse_newline_list(t);
    if t.peek() == Some(b')') { t.emit(TKind::Verbatim, ")"); t.pos += 1; }
}

fn parse_cmd_sub_inner(t: &mut Tokenizer) {
    parse_compound_list(t, &[b")"]);
}

fn parse_backtick(t: &mut Tokenizer, needs_quote: bool) {
    assert_eq!(t.peek(), Some(b'`'));
    t.pos += 1; // skip `
    if needs_quote { t.emit(TKind::NQOpen, "\""); t.emit(TKind::CmdSubOpen, "$("); }
    else { t.emit(TKind::CmdSubOpen, "`"); }
    loop {
        if t.pos >= t.input.len() { break; }
        if t.peek() == Some(b'`') { t.pos += 1; break; }
        let start = t.pos;
        parse_compound_list(t, &[b"`"]);
        if t.peek() == Some(b'`') { t.pos += 1; break; }
        if t.pos == start { let c = t.advance().unwrap_or(b'`'); t.emit(TKind::Verbatim, &(c as char).to_string()); }
    }
    if needs_quote { t.emit(TKind::CmdSubClose, ")"); t.emit(TKind::NQClose, "\""); }
    else { t.emit(TKind::CmdSubClose, "`"); }
}

fn emit_pitfall_error(t: &mut Tokenizer, _var: &str, pos: usize) {
    let (line, col) = find_line(t, pos);
    let fname = t.fname.unwrap_or("stdin");
    let _ = io::stderr().write_all(
        format!("{}: Unsupported syntax: Syntactic pitfall\n{}\n{}\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\nTry this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j\n\nHere is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".\n\nSyntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code \u{2013} code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.\n",
            fname, line, format!("{}^^^", " ".repeat(col))
        ).as_bytes()
    );
    t.had_error = true;
}

fn find_line(t: &Tokenizer, pos: usize) -> (String, usize) {
    let mut ls = 0;
    for (i, &c) in t.input[..pos].iter().enumerate() {
        if c == b'\n' { ls = i + 1; }
    }
    let le = t.input[ls..].iter().position(|&c| c == b'\n').map(|i| ls + i).unwrap_or(t.input.len());
    let line = std::str::from_utf8(&t.input[ls..le]).unwrap_or("").to_string();
    (line, pos - ls)
}

