        }
        let s = t.collect_str(start).to_string();
        t.emit(TKind::SafeVar, &s);
        return;
    }

    // ${@} ${*} -> needs quoting
    if matches!(peek, b'@' | b'*') && t.peek_at(1) == Some(b'}') {
        t.pos += 2; // skip @ or *, }
        let orig = t.collect_str(start).to_string();
        t.emit_trans(TKind::UVar, &orig, &format!("\"{}\"", orig));
        return;
    }

    // ${?} ${$} ${!} ${#} special - safe
    if matches!(peek, b'?' | b'$' | b'!') && t.peek_at(1) == Some(b'}') {
        t.pos += 2;
        let s = t.collect_str(start).to_string();
        t.emit(TKind::SafeVar, &s);
        return;
