    let orig = t.collect_str(start).to_string();

    // Determine transformation
    let trans = if suffix.is_empty() {
        // ${var} -> "$var" (remove braces)
        if !name.is_empty() && is_is(name.as_bytes()[0]) && name.bytes().all(|c| is_ic(c)) {
            format!("\"${}\"", name) // braces removed
        } else {
