# Now add parse_case_expr_word function - parses the case expression with proper coloring
cat >> /home/agent/src/main.rs << 'EOF'

fn parse_case_expr_word(t: &mut Tokenizer) {
    // Parse the case expression in magic context
    // $var is colored as SafeVar, "string" as DQ, etc.
    // No quoting transformation - magic context
    if t.pos >= t.input.len() { return; }

    loop {
        if t.pos >= t.input.len() { break; }
        let c = t.input[t.pos];
        if c == b'\n' { break; }
        if c == b' ' || c == b'\t' { break; } // stop at spaces before "in"
        if t.input[t.pos..].starts_with(b"in") && !is_ic(t.input.get(t.pos + 2).copied().unwrap_or(0)) { break; }

        match c {
            b'"' => parse_dq(t, false), // Already colored properly
            b'\'' => parse_sq(t),
            b'$' => {
                // In case context, $var is safe (magic context)
                let c2 = t.peek_at(1).unwrap_or(0);
                if c2 == b'(' {
                    if t.peek_at(2) == Some(b'(') {
                        let s = read_dollar_arith(t);
                        t.emit(TKind::Arith, &s);
                    } else {
                        t.pos += 2;
                        t.emit(TKind::CmdSubOpen, "$(");
                        parse_cmd_sub_inner(t);
                        if t.peek() == Some(b')') { t.emit(TKind::CmdSubClose, ")"); t.pos += 1; }
                    }
                } else if c2 == b'{' {
                    // ${...} - treat as safe
                    let start = t.pos;
                    t.pos += 2;
                    let mut depth = 1i32;
                    while t.pos < t.input.len() {
                        match t.input[t.pos] {
                            b'{' => { depth += 1; t.pos += 1; }
                            b'}' => { depth -= 1; t.pos += 1; if depth == 0 { break; } }
                            _ => { t.pos += 1; }
                        }
                    }
                    let s = std::str::from_utf8(&t.input[start..t.pos]).unwrap_or("").to_string();
                    t.emit(TKind::SafeVar, &s);
                } else if c2.is_ascii_alphanumeric() || c2 == b'_' || matches!(c2, b'@' | b'*' | b'?' | b'$' | b'!' | b'#') {
                    let start = t.pos;
                    t.pos += 1; // $
                    while t.pos < t.input.len() && is_ic(t.input[t.pos]) { t.pos += 1; }
                    let s = std::str::from_utf8(&t.input[start..t.pos]).unwrap_or("").to_string();
                    t.emit(TKind::SafeVar, &s);
                } else {
                    t.emit(TKind::Verbatim, "$");
                    t.pos += 1;
                }
            }
            _ => {
                let start = t.pos;
                while t.pos < t.input.len() {
                    let c = t.input[t.pos];
                    if c == b'\n' || c == b'"' || c == b'\'' || c == b'$' || c == b' ' || c == b'\t' { break; }
                    if t.input[t.pos..].starts_with(b"in") && !is_ic(t.input.get(t.pos + 2).copied().unwrap_or(0)) { break; }
                    t.pos += 1;
                }
                let s = std::str::from_utf8(&t.input[start..t.pos]).unwrap_or("").to_string();
                if !s.is_empty() { t.emit(TKind::Verbatim, &s); }
            }
        }
    }
}
