// Wrapper for parse_dq_dollar_brace that accepts a "can_remove_braces" hint
fn parse_dq_dollar_brace_ctx(t: &mut Tokenizer, can_remove_standalone: bool) {
    let saved_len = t.tokens.len();
    parse_dq_dollar_brace(t);

    // If can_remove_standalone and the last token is DQVar with simple name, make it DQVarRm
    if can_remove_standalone {
        if let Some(tok) = t.tokens.last_mut() {
            if tok.kind == TKind::DQVar {
                // Check if it's a simple ${name} (can remove braces)
                if tok.text.starts_with("${") && tok.text.ends_with('}') {
                    let inner = &tok.text[2..tok.text.len()-1];
                    // Only if inner is a simple identifier
                    if inner.len() > 0 && is_is(inner.as_bytes()[0]) && inner.bytes().all(|c| is_ic(c)) {
                        tok.kind = TKind::DQVarRm;
                        tok.transform = format!("${}", inner);
                    }
                }
            }
        }
    }
}
