new = '''fn parse_double_bracket(t: &mut Tokenizer) {
    // [[ starts with "[[" colored as arith, then content with syntax highlighting
    // The [[ itself and ]] are colored as arith
    // $var inside is colored as variable, "strings" as DQ, etc.
