    let space_start = t.pos;
    // The "[[ " includes the space after
    let bracket_open;
    if t.peek() == Some(b\' \') {
        t.pos += 1; // include the space
        bracket_open = "[[ ".to_string();
    } else {
        bracket_open = "[[".to_string();
    }
    t.emit(TKind::DQArith, &bracket_open); // Reuse DQArith kind for arith-colored text

    // Parse content with syntax-like coloring
    // $var -> SafeVar (colored as variable), "str" -> DQ, plain text -> DQArith
