# Add the is_valid_assign_name function:
cat >> /home/agent/src/main.rs << 'EOF'

fn is_valid_assign_name(s: &[u8]) -> bool {
    // Valid assignment LHS: identifier chars plus optional [subscript]
    // e.g., "arr[0]", "map["key"]", etc.
    if s.is_empty() || !is_is(s[0]) { return false; }
    let mut i = 0;
    while i < s.len() && is_ic(s[i]) { i += 1; }
    if i == s.len() { return true; } // simple identifier
    // Check for [subscript]
    if s[i] == b'[' {
        // Skip to matching ]
        let mut depth = 1;
        i += 1;
        while i < s.len() && depth > 0 {
            if s[i] == b'[' { depth += 1; }
            else if s[i] == b']' { depth -= 1; }
            i += 1;
        }
        return i == s.len(); // must be at end
    }
    false
}
EOF
