                // Already in DQ color
                out.push(\'"\');
                if in_bracket == 0 {
                    // Outside [[ ]] - emit RESET to end DQ color
                    out.push_str(RESET);
                }
                // Inside [[ ]] - next token (DBrArith) will self-reset DQ color
                cur_color = None;
                in_dq = false;
                pending_reset = true; // will emit RESET before next uncolored text
            }'''

