# This requires either:
# 1. Post-processing: merge adjacent UVar tokens before rendering
# 2. During parsing: accumulate adjacent vars into one token

# Let me implement option 1: post-process to merge adjacent UVar tokens.

# Algorithm:
# Scan through tokens. When we see a UVar or NQOpen/NQClose sequence,
# look ahead to see if there's another UVar immediately following.
# If yes, merge them.

# Actually the transform output is simpler: just look at render_transform.
# In render_transform, when we see a UVar("$var1", "\"$var1\"") followed by UVar("$var2", "\"$var2\""),
# we want to output "$var1$var2" (not "$var1""$var2").

# The issue is about the SEQUENCE: UVar1 + UVar2
# Both want to wrap themselves in quotes.
# The result: "$var1" + "$var2" = two separate quoted strings.
# But bash DOESN'T merge adjacent quoted strings automatically - they DO concatenate.
# But the original shellharden merges them for consistency.

# Let me implement a post-processing step to merge adjacent UVar tokens:
cat >> /home/agent/src/main.rs << 'EOF'

// Merge adjacent UVar tokens into combined "var1var2" form
// e.g., $var1$var2 -> "$var1$var2" (not "$var1""$var2")
fn merge_adjacent_uvars(tokens: &mut Vec<Token>) {
    let mut i = 0;
    while i < tokens.len() {
        if tokens[i].kind == TKind::UVar {
            // Look ahead for adjacent UVar tokens
            let mut j = i + 1;
            let mut merged_orig = tokens[i].text.clone();
            let mut merged_trans_inner = strip_dq(&tokens[i].transform).to_string();
            let mut merged = false;

            while j < tokens.len() {
                match tokens[j].kind {
                    TKind::UVar => {
                        let next_orig = tokens[j].text.clone();
                        let next_trans = strip_dq(&tokens[j].transform).to_string();
                        merged_orig.push_str(&next_orig);
                        merged_trans_inner.push_str(&next_trans);
                        merged = true;
                        j += 1;
                    }
                    TKind::NQOpen | TKind::NQClose => {
                        j += 1; // skip quote markers
                    }
                    _ => break,
                }
            }

            if merged {
                let trans = format!("\"{}\"", merged_trans_inner);
                tokens[i].text = merged_orig;
                tokens[i].transform = trans;
                tokens.drain(i+1..j);
            }
        }
        i += 1;
    }
}
EOF
