            let uvar_orig = tokens[i].text.clone();
            let uvar_trans = strip_dq_str(&tokens[i].transform);
            // Remove the outer quotes from uvar_trans to get the variable reference
            // uvar_trans is like "$var" or "${var[@]}" or "$@" etc.

            // Find the DQ string end
            let dq_start = i + 1;
            let mut dq_end = dq_start + 1;
            while dq_end < tokens.len() && tokens[dq_end].kind != TKind::DQClose {
                dq_end += 1;
            }
            if dq_end >= tokens.len() { i += 1; continue; }

            // Get the DQ content
            // Check if we need braces: look at first DQText token
            let first_dq_content = tokens.get(dq_start + 1);
            let needs_braces = if let Some(tok) = first_dq_content {
                if tok.kind == TKind::DQText {
                    tok.text.chars().next().map(|c| c.is_ascii_alphanumeric() || c == \'_\').unwrap_or(false)
                } else {
                    // First is DQVar, DQCmdOpen, etc. - always need braces
                    true
                }
            } else {
                false // empty DQ string - no braces needed
            };

            // Build merged var reference
            let var_ref = if needs_braces && uvar_trans.starts_with(\'$\') && !uvar_trans.starts_with("${") {
                // Need to add braces: "$var" -> "${var}"
                format!("${{{}}}",  &uvar_trans[1..])
            } else {
                uvar_trans.to_string()
            };

