            let new_trans = format!("\\"{}", var_ref);

            // Create a new DQVar token at the start of the DQ string
            let dq_var_tok = Token { kind: TKind::DQVar, text: uvar_orig.clone(), transform: var_ref.clone() };
            // The orig for display: original $var text

            // Remove the UVar token
            tokens.remove(i);
            // Insert DQVar at start of DQ content (after DQOpen)
            tokens.insert(i + 1, dq_var_tok);

            // Update the UVar -> we actually changed the structure
            // The token at i is now DQOpen, i+1 is our new DQVar(orig=$var)
            // We also need to update the original text tracking for suggest mode.
            // For the UVar merge: the outer DQ now starts with ${var}...
            // For suggest mode rendering, we need to show:
            // [ADD]"[VAR]${var}[REMOVE]"[DQ]content"
            // This means we also keep a special marker.
            // For simplicity, let's just mark the DQOpen as a "merged" start.

            // Actually, let me just not merge for now and handle it differently.
            // Revert: put the UVar back
            tokens.remove(i + 1); // remove inserted DQVar
            // Don\'t merge - too complex for now
            i += 1;
            continue;
        }

        // Case 2: adjacent UVar tokens -> merge
        if tokens[i].kind == TKind::UVar {
            let mut j = i + 1;
            let mut merged_orig = tokens[i].text.clone();
            let mut merged_trans_inner = strip_dq_str(&tokens[i].transform).to_string();
            let mut merged = false;

            while j < tokens.len() {
                match tokens[j].kind {
                    TKind::UVar => {
                        let next_orig = tokens[j].text.clone();
                        let next_trans = strip_dq_str(&tokens[j].transform).to_string();
                        merged_orig.push_str(&next_orig);
                        merged_trans_inner.push_str(&next_trans);
                        merged = true;
                        j += 1;
                    }
                    TKind::NQOpen | TKind::NQClose => { j += 1; }
                    _ => break,
                }
            }

            if merged {
                let trans = format!("\\"{}\\"", merged_trans_inner);
                tokens[i].text = merged_orig;
                tokens[i].transform = trans;
                tokens.drain(i+1..j);
            }
        }
        i += 1;
    }
}

fn strip_dq_str(s: &str) -> &str {
