# If parse_arg makes no progress, the loop runs forever.
# Also: when parse_select has "select opt in", skip_blanks is called AFTER reading var.
# Then skip_blanks_no_emit should be used for the space.

# But the loop issue: parse_arg with "a" should work.
# Wait: what does parse_arg do with "a"?
# "a" is just a plain word, should be emitted as Verbatim.
# But then the loop comes back and we're still at " b; do" (space before b).
# The loop checks for ';', '\n', or "do" - not for spaces!
# We're at " " (space), not ';' or '\n' or "do".
# parse_arg is called with "a " - but it stops at ' ' (because term_chars doesn't include ' ').
# Wait: parse_arg has "if !term_chars.contains(&b' ') && (c == b' ' || c == b'\t') { break; }"
# term_chars = [b';', b'\n']
# So ' ' is NOT in term_chars, and c == ' ' -> break!
# So parse_arg stops immediately at ' ' (the space before 'b').
# Then the outer loop sees ' ' at t.pos, which is NOT ';' or '\n' or "do".
# The loop continues, calls parse_arg again which breaks immediately again.
# INFINITE LOOP!

# Fix: after parse_arg in the items loop, skip whitespace:
python3 << 'PYEOF'
with open('/home/agent/src/main.rs', 'r') as f:
    content = f.read()

old = '''    // items are verbatim until ; or do
    let start = t.pos;
    loop {
        if t.pos >= t.input.len() { break; }
        let c = t.input[t.pos];
        if c == b\';\' || c == b\'\\n\' { break; }
        if at_kw(t, b"do") { break; }
        // Parse items as regular args
        parse_arg(t, false, &[b\';\', b\'\\n\'], &[b"do"]);
    }'''

new = '''    // items are verbatim until ; or do
    loop {
        skip_inline_ws(t);
        if t.pos >= t.input.len() { break; }
        let c = t.input[t.pos];
        if c == b\';\' || c == b\'\\n\' { break; }
        if at_kw(t, b"do") { break; }
        let start = t.pos;
        // Parse items as regular args
        parse_arg(t, false, &[b\';\', b\'\\n\'], &[b"do"]);
        if t.pos == start { break; } // no progress, stop
    }'''

if old in content:
    content = content.replace(old, new)
    print("fixed select items loop")
else:
    print("NOT FOUND")

# Also fix skip_blanks -> skip_blanks_no_emit before "select " keyword:
old2 = '''    t.emit(TKind::Keyword, "select ");
    skip_blanks(t);
    let var = t.read_ident();'''
new2 = '''    skip_blanks_no_emit(t); // skip spaces after "select" keyword
    t.emit(TKind::Keyword, "select ");
    let var = t.read_ident();'''
if old2 in content:
    content = content.replace(old2, new2)
    print("fixed select blanks")

with open('/home/agent/src/main.rs', 'w') as f:
    f.write(content)
