fn parse_proc_sub_content(t: &mut Tokenizer) {
    // Parse content of process substitution <(...) - commands not colored, but vars are
    // This mimics the behavior of the reference implementation
    let mut depth = 1u32;
    while t.pos < t.input.len() && depth > 0 {
        let c = t.input[t.pos];
        match c {
            b')' => {
                depth -= 1;
                if depth == 0 { break; }
                t.emit(TKind::Verbatim, ")");
                t.pos += 1;
            }
            b'(' => { 
                depth += 1; 
                t.emit(TKind::Verbatim, "(");
                t.pos += 1; 
            }
            b'$' => {
                // Variable/substitution - parse but mark as needing quotes
                let c2 = t.peek_at(1).unwrap_or(0);
                if c2 == b'(' {
                    if t.peek_at(2) == Some(b'(') {
                        let s = read_dollar_arith(t);
                        t.emit(TKind::Arith, &s);
                    } else {
                        t.pos += 2;
                        t.emit(TKind::NQOpen, "\"");
                        t.emit(TKind::CmdSubOpen, "$(");
                        parse_cmd_sub_inner(t);
                        if t.peek() == Some(b')') { t.emit(TKind::CmdSubClose, ")"); t.pos += 1; }
                        t.emit(TKind::NQClose, "\"");
                    }
                } else {
                    parse_dollar_arg(t, false);
                }
            }
            b'"' => parse_dq(t, false),
            b'\'' => parse_sq(t),
            b'`' => parse_backtick(t, true),
            _ => {
                // Verbatim text (including command names, operators, etc.)
                let start = t.pos;
                while t.pos < t.input.len() {
                    let c = t.input[t.pos];
                    if c == b')' || c == b'(' || c == b'$' || c == b'"' || c == b'\'' || c == b'`' { break; }
                    t.pos += 1;
                }
                let s = t.collect_str(start).to_string();
                if !s.is_empty() { t.emit(TKind::Verbatim, &s); }
            }
        }
    }
}
